"use client";

import { FormEvent, useEffect, useMemo, useState } from "react";
import {
  Activity, ArrowDownLeft, ArrowDownRight, ArrowRight, ArrowUpRight, Boxes,
  Check, ChevronDown, ChevronRight, CircleDollarSign, ClipboardList, Download,
  FileChartColumn, FileText, LayoutDashboard, Menu, Package, Pencil, Plus,
  Printer, Search, Settings2, ShoppingBag, Trash2, Wallet, X, Eye, Factory,
} from "lucide-react";

type Section = "Overview" | "Inventory" | "Vendors" | "Purchases" | "Sales" | "Invoices" | "Today's expenses" | "Cash flow" | "Reports" | "Activity log" | "Profile";
type VendorProduct = { id: string; name: string; sku: string; category: string };
type Vendor = { id: string; name: string; phone: string; email: string; address: string; bank: string; accountName: string; accountNumber: string; ifsc: string; createdAt: string; products: VendorProduct[] };
type PurchaseLine = { id: string; productId: string; name: string; sku: string; category: string; quantity: number; materialCost: number; manufacturingCost: number; returned: number };
type PurchaseExpense = { id: string; description: string; category: string; amount: number; payee: string };
type Purchase = { id: string; vendorId: string; vendorName: string; reference: string; date: string; paid: number; items: PurchaseLine[]; extraExpenses?: PurchaseExpense[]; sourcePaymentId?: string };
type Expense = { id: string; date: string; category: string; payee: string; description: string; amount: number; method: string; reference: string; sourcePaymentId?: string };
type ProcessEntry = { id: string; process: string; quantity: number; date: string; status: "In process" | "Completed"; note: string };
type Batch = { id: string; purchaseId: string; lineId: string; vendorId: string; vendorName: string; productId: string; product: string; sku: string; category: string; received: string; quantity: number; remaining: number; materialCost: number; manufacturingCost: number; warehouse: string; processes?: ProcessEntry[] };
type SaleLine = { id: string; productId: string; product: string; quantity: number; price: number; taxRate: number; cogs: number; allocations: { batchId: string; quantity: number }[] };
type Order = { id: string; invoice?: string; customer: string; channel: string; created: string; status: "Draft" | "Confirmed" | "Invoiced" | "Paid"; paid: number; items: SaleLine[] };
type PurchaseReturn = { id: string; purchaseId: string; vendorId: string; vendorName: string; lineId: string; productId: string; product: string; quantity: number; amount: number; disposition: "Refund due" | "Vendor credit"; refunded: number; reason: string; date: string };
type Payment = { id: string; date: string; kind: "Customer receipt" | "Supplier payment" | "Supplier refund"; party: string; reference: string; method: string; amount: number; linkId: string; sourcePaymentId?: string };
type LogEntry = { id: string; dateTime: string; actor: string; action: string; record: string; detail: string };
type Profile = { name: string; email: string; phone: string; address: string; bank: string; accountName: string; accountNumber: string; ifsc: string; gstin: string };
type Store = { vendors: Vendor[]; purchases: Purchase[]; batches: Batch[]; orders: Order[]; returns: PurchaseReturn[]; payments: Payment[]; expenses: Expense[]; logs: LogEntry[]; profile: Profile };
type Modal = "purchase" | "vendor" | "product" | "order" | "supplier-payment" | "customer-payment" | "supplier-refund" | "purchase-return" | "invoice" | "reset" | "edit-payment" | "process" | "expense" | "edit-expense" | null;
type CashFlowFilter = "All activity" | "Customer receipts" | "Purchases" | "Supplier payments" | "Other expenses";
type CashFlowRow = {id:string;date:string;kind:CashFlowFilter|"Supplier refunds";party:string;reference:string;amount:number;sourcePaymentId?:string;sourceName:string;status:string;detailKind:"payment"|"purchase"|"expense"};
type DetailView = {kind:"supplier"|"customer"|"product"|"purchase"|"expense"|"payment";id:string};

const STORE_KEY = "d2-garments-workspace-v3";
const PREVIOUS_KEY = "d2-garments-workspace-v2";
const EMPTY_PROFILE: Profile = { name: "D2 Garments", email: "", phone: "", address: "", bank: "", accountName: "", accountNumber: "", ifsc: "", gstin: "" };
const EMPTY: Store = { vendors: [], purchases: [], batches: [], orders: [], returns: [], payments: [], expenses: [], logs: [], profile: EMPTY_PROFILE };
const sections: { name: Section; icon: typeof LayoutDashboard }[] = [
  { name: "Overview", icon: LayoutDashboard }, { name: "Inventory", icon: Boxes },
  { name: "Vendors", icon: Package }, { name: "Purchases", icon: ClipboardList },
  { name: "Sales", icon: ShoppingBag }, { name: "Invoices", icon: FileText },
  { name: "Today's expenses", icon: CircleDollarSign }, { name: "Cash flow", icon: Wallet },
  { name: "Reports", icon: FileChartColumn }, { name: "Activity log", icon: Activity },
  { name: "Profile", icon: Settings2 },
];
const orderTypes = ["Retail", "Bulk", "Bulk order", "Container", "Wholesale"];
const money = (amount: number) => `₹${Math.round(amount).toLocaleString("en-IN")}`;
const isoDate = () => { const date=new Date();date.setMinutes(date.getMinutes()-date.getTimezoneOffset());return date.toISOString().slice(0,10); };
const id = (prefix: string) => `${prefix}-${Date.now().toString().slice(-8)}-${Math.floor(Math.random() * 90 + 10)}`;
const dateText = (date: string) => date ? new Date(`${date.slice(0, 10)}T12:00:00`).toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" }) : "—";
const lineTotal = (line: PurchaseLine) => line.quantity * (line.materialCost + line.manufacturingCost);
const purchaseTotal = (purchase: Purchase) => purchase.items.reduce((sum, line) => sum + lineTotal(line), 0);
const purchaseExtraTotal = (purchase: Purchase) => (purchase.extraExpenses??[]).reduce((sum,item)=>sum+item.amount,0);
const saleSubtotal = (order: Order) => order.items.reduce((sum, item) => sum + item.quantity * item.price, 0);
const saleTotal = (order: Order) => order.items.reduce((sum, item) => sum + item.quantity * item.price * (1 + item.taxRate / 100), 0);
const saleCost = (order: Order) => order.items.reduce((sum, item) => sum + item.cogs, 0);
const returnedTotal = (store: Store, purchaseId: string) => store.returns.filter(item => item.purchaseId === purchaseId).reduce((sum, item) => sum + item.amount, 0);
function receiptAllocated(store:Store,receiptId:string,excludePurchaseId="",excludeExpenseId="",excludePaymentId="") { const purchases=store.purchases.filter(p=>p.id!==excludePurchaseId&&p.sourcePaymentId===receiptId).reduce((sum,p)=>sum+purchaseTotal(p)+purchaseExtraTotal(p),0);const expenses=store.expenses.filter(e=>e.id!==excludeExpenseId&&e.sourcePaymentId===receiptId).reduce((sum,e)=>sum+e.amount,0);const supplierPayments=store.payments.filter(p=>p.id!==excludePaymentId&&p.kind==="Supplier payment"&&p.sourcePaymentId===receiptId&&store.purchases.find(x=>x.id===p.linkId)?.sourcePaymentId!==receiptId).reduce((sum,p)=>sum+p.amount,0);return purchases+expenses+supplierPayments; }
const daysOld = (date:string) => Math.max(0,Math.floor((new Date(`${isoDate()}T12:00:00`).getTime()-new Date(`${date.slice(0,10)}T12:00:00`).getTime())/86400000));
const purchaseDue = (store: Store, purchase: Purchase) => Math.max(0, purchaseTotal(purchase) - returnedTotal(store, purchase.id) - purchase.paid);
const refundDue = (store: Store, purchaseId: string) => store.returns.filter(item => item.purchaseId === purchaseId && item.disposition === "Refund due").reduce((sum, item) => sum + item.amount - item.refunded, 0);
const newVendor = (name: string, data?: Partial<Vendor>): Vendor => ({ id: id("VEN"), name, phone: "", email: "", address: "", bank: "", accountName: "", accountNumber: "", ifsc: "", createdAt: isoDate(), products: [], ...data });
const slug = (text: string) => text.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

function buildInvoicesPdf(orders: Order[], profile: Profile) {
  const ascii = (value: string) => value.normalize("NFKD").replace(/[^\x20-\x7E]/g, "?").replace(/\\/g, "\\\\").replace(/\(/g, "\\(").replace(/\)/g, "\\)");
  const objects: string[] = [];
  const addObject = (value: string) => { objects.push(value); return objects.length; };
  const pagesId = addObject("");
  const fontId = addObject("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>");
  const pageIds: number[] = [];
  for (const order of orders) {
    const invoice = order.invoice || `INV-${order.id.replace("ORD-", "")}`;
    const lines = [
      profile.name, "SALES INVOICE", "", `Invoice: ${invoice}`, `Order: ${order.id}`, `Date: ${dateText(order.created)}`,
      "", `Bill to: ${order.customer}`, `Channel: ${order.channel}`, "", "PRODUCT                         QTY       UNIT PRICE          AMOUNT",
      ...order.items.map(item => `${item.product}                       ${item.quantity}       INR ${Math.round(item.price)}       INR ${Math.round(item.quantity * item.price)}`),
      "", `Subtotal: INR ${Math.round(saleSubtotal(order))}`, `Tax: INR ${Math.round(saleTotal(order) - saleSubtotal(order))}`,
      `Invoice total: INR ${Math.round(saleTotal(order))}`, `Paid: INR ${Math.round(order.paid)}`,
      `Balance due: INR ${Math.round(Math.max(0, saleTotal(order) - order.paid))}`, "", `Address: ${profile.address || "Not provided"}`,
      `Email: ${profile.email || "Not provided"}    Phone: ${profile.phone || "Not provided"}`, `GSTIN: ${profile.gstin || "Not provided"}`,
      `Bank: ${profile.bank || "Not provided"}    Account: ${profile.accountNumber || "Not provided"}`, `IFSC: ${profile.ifsc || "Not provided"}`,
    ];
    const pageHeight = Math.max(842, 110 + lines.length * 22);
    const commands = lines.map((line, index) => `BT /F1 ${index < 2 ? 16 : 10} Tf 1 0 0 1 48 ${pageHeight - 52 - index * 22} Tm (${ascii(line).slice(0, 110)}) Tj ET`).join("\n");
    const contentId = addObject(`<< /Length ${new TextEncoder().encode(commands).length} >>\nstream\n${commands}\nendstream`);
    const pageId = addObject(`<< /Type /Page /Parent ${pagesId} 0 R /MediaBox [0 0 612 ${pageHeight}] /Resources << /Font << /F1 ${fontId} 0 R >> >> /Contents ${contentId} 0 R >>`);
    pageIds.push(pageId);
  }
  objects[pagesId - 1] = `<< /Type /Pages /Kids [${pageIds.map(id => `${id} 0 R`).join(" ")}] /Count ${pageIds.length} >>`;
  const catalogId = addObject(`<< /Type /Catalog /Pages ${pagesId} 0 R >>`);
  let pdf = "%PDF-1.4\n";
  const offsets = [0];
  objects.forEach((object, index) => { offsets.push(new TextEncoder().encode(pdf).length); pdf += `${index + 1} 0 obj\n${object}\nendobj\n`; });
  const xrefOffset = new TextEncoder().encode(pdf).length;
  pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n${offsets.slice(1).map(offset => `${String(offset).padStart(10, "0")} 00000 n \n`).join("")}trailer\n<< /Size ${objects.length + 1} /Root ${catalogId} 0 R >>\nstartxref\n${xrefOffset}\n%%EOF`;
  return new Blob([new TextEncoder().encode(pdf)], { type: "application/pdf" });
}

function migratePrevious(previous: Partial<Store> & Record<string, unknown>): Store {
  if (Array.isArray(previous.vendors)) return { ...EMPTY, ...previous, profile: { ...EMPTY_PROFILE, ...(previous.profile as Profile | undefined) } } as Store;
  const vendors: Vendor[] = [];
  const purchases: Purchase[] = [];
  const batches: Batch[] = [];
  const productIds = new Map<string, VendorProduct>();
  const legacyPurchases = (previous.purchases ?? []) as Array<Record<string, unknown>>;
  const legacyBatches = (previous.batches ?? []) as Array<Record<string, unknown>>;
  for (const old of legacyPurchases) {
    const name = String(old.supplier ?? "Legacy supplier");
    let vendor = vendors.find(item => item.name.toLowerCase() === name.toLowerCase());
    if (!vendor) { vendor = newVendor(name); vendors.push(vendor); }
    const rawItems = Array.isArray(old.items) ? old.items as Array<Record<string, unknown>> : [old];
    const items: PurchaseLine[] = rawItems.map(raw => {
      const productName = String(raw.name ?? raw.product ?? "Unnamed product");
      const key = `${vendor!.id}:${slug(productName)}`;
      let product = productIds.get(key);
      if (!product) { product = { id: id("SKU"), name: productName, sku: "", category: String(raw.category ?? "Other") }; productIds.set(key, product); vendor!.products.push(product); }
      const oldBatch = legacyBatches.find(b => b.purchaseId === old.id && String(b.product) === productName);
      return { id: String(raw.id ?? id("ITM")), productId: product.id, name: product.name, sku: String(raw.sku ?? oldBatch?.sku ?? ""), category: String(raw.category ?? oldBatch?.category ?? "Other"), quantity: Number(raw.quantity ?? 0), materialCost: Number(raw.materialCost ?? 0), manufacturingCost: Number(raw.manufacturingCost ?? 0), returned: 0 };
    });
    purchases.push({ id: String(old.id ?? id("PUR")), vendorId: vendor.id, vendorName: vendor.name, reference: String(old.reference ?? ""), date: String(old.date ?? isoDate()), paid: Number(old.paid ?? 0), items });
  }
  for (const raw of legacyBatches) {
    const purchase = purchases.find(item => item.id === raw.purchaseId);
    const line = purchase?.items.find(item => item.name === raw.product);
    if (purchase && line) batches.push({ id: String(raw.id ?? id("LOT")), purchaseId: purchase.id, lineId: line.id, vendorId: purchase.vendorId, vendorName: purchase.vendorName, productId: line.productId, product: line.name, sku: line.sku, category: line.category, received: String(raw.received ?? isoDate()), quantity: Number(raw.quantity ?? line.quantity), remaining: Number(raw.remaining ?? 0), materialCost: Number(raw.materialCost ?? line.materialCost), manufacturingCost: Number(raw.manufacturingCost ?? line.manufacturingCost), warehouse: String(raw.warehouse ?? "Warehouse A") });
  }
  const orders = ((previous.orders ?? []) as Array<Record<string, unknown>>).map(raw => {
    const oldItems = Array.isArray(raw.items) ? raw.items as Array<Record<string, unknown>> : [raw];
    return { id: String(raw.id ?? id("ORD")), invoice: raw.invoice ? String(raw.invoice) : undefined, customer: String(raw.customer ?? ""), channel: String(raw.channel ?? "Bulk"), created: String(raw.created ?? isoDate()), status: (raw.status ?? "Draft") as Order["status"], paid: Number(raw.paid ?? 0), items: oldItems.map(item => { const name = String(item.product ?? item.name ?? ""); return { id: String(item.id ?? id("SLI")), productId: batches.find(batch => batch.product === name)?.productId ?? "", product: name, quantity: Number(item.quantity ?? 0), price: Number(item.price ?? 0), taxRate: Number(item.taxRate ?? 0), cogs: Number(item.cogs ?? raw.cogs ?? 0), allocations: [] }; }) };
  }) as Order[];
  const payments = ((previous.payments ?? []) as Array<Record<string, unknown>>).map(raw => {
    const kind = String(raw.kind ?? (raw.direction === "in" ? "Customer receipt" : "Supplier payment")) as Payment["kind"];
    const party = String(raw.party ?? "");
    const linkId = String(raw.linkId ?? (kind === "Customer receipt" ? orders.find(o=>o.customer===party)?.id : purchases.find(p=>p.vendorName===party)?.id) ?? "");
    return { id: String(raw.id ?? id("PAY")), date: String(raw.date ?? isoDate()), kind, party, reference: String(raw.reference ?? ""), method: String(raw.method ?? "Other"), amount: Number(raw.amount ?? 0), linkId };
  });
  return { ...EMPTY, vendors, purchases, batches, orders, payments, logs: (previous.logs ?? []) as LogEntry[], profile: { ...EMPTY_PROFILE, ...(previous.profile as Partial<Profile> ?? {}) } };
}

function EmptyState({ icon: Icon, title, text, action, onAction }: { icon: typeof Package; title: string; text: string; action?: string; onAction?: () => void }) {
  return <div className="empty-state"><span className="empty-icon"><Icon size={24}/></span><strong>{title}</strong><p>{text}</p>{action && onAction && <button className="button primary" onClick={onAction}><Plus size={17}/>{action}</button>}</div>;
}
function detailTitle(store:Store,detail:DetailView){if(detail.kind==="supplier")return store.vendors.find(v=>v.id===detail.id)?.name||"Supplier details";if(detail.kind==="purchase")return `Purchase · ${detail.id}`;if(detail.kind==="product"){const b=store.batches.find(x=>x.productId===detail.id);return b?`${b.product} · ${b.vendorName}`:"Product history";}if(detail.kind==="customer")return detail.id;if(detail.kind==="expense")return `Expense · ${detail.id}`;return `Payment · ${detail.id}`;}
function RecordDetailPage({store,detail,onOpen,onPayment,onInvoice}:{store:Store;detail:DetailView;onOpen:(kind:DetailView["kind"],id:string)=>void;onPayment:(id:string)=>void;onInvoice:(id:string)=>void}){
 const supplier=detail.kind==="supplier"?store.vendors.find(v=>v.id===detail.id):undefined;const purchase=detail.kind==="purchase"?store.purchases.find(p=>p.id===detail.id):undefined;const batches=detail.kind==="product"?store.batches.filter(b=>b.productId===detail.id):[];const orders=detail.kind==="customer"?store.orders.filter(o=>o.customer===detail.id&&o.status!=="Draft"):[];const customerReceipts=detail.kind==="customer"?store.payments.filter(p=>p.kind==="Customer receipt"&&(p.party===detail.id||orders.some(o=>o.id===p.linkId))):[];const supplierPurchases=supplier?store.purchases.filter(p=>p.vendorId===supplier.id):[];const payments=purchase?store.payments.filter(p=>p.kind==="Supplier payment"&&p.linkId===purchase.id):[];const source=purchase?.sourcePaymentId?store.payments.find(p=>p.id===purchase.sourcePaymentId):undefined;const receipt=detail.kind==="payment"?store.payments.find(p=>p.id===detail.id):undefined;const expense=detail.kind==="expense"?store.expenses.find(e=>e.id===detail.id):undefined;
 return <section className="panel data-panel record-detail"><button className="button secondary" onClick={()=>onOpen("supplier","")}>Back to {detail.kind==="supplier"?"Vendors":detail.kind==="purchase"?"Purchases":detail.kind==="product"?"Inventory":detail.kind==="customer"?"Sales":"Cash flow"}</button>
 {supplier&&<><h2>Supplier account · {supplier.name}</h2><p>{supplier.phone} · {supplier.email} · {supplier.address}</p><div className="ledger-summary"><div><span>Purchase records</span><strong>{supplierPurchases.length}</strong></div><div><span>Total purchases</span><strong>{money(supplierPurchases.reduce((s,p)=>s+purchaseTotal(p)+purchaseExtraTotal(p),0))}</strong></div><div><span>Supplier balance due</span><strong>{money(supplierPurchases.reduce((s,p)=>s+purchaseDue(store,p),0))}</strong></div><div><span>Products</span><strong>{supplier.products.length}</strong></div></div><h3>Purchase and payment history</h3><Table><thead><tr><th>DATE / REFERENCE</th><th>PRODUCTS</th><th>VALUE</th><th>PAID</th><th>DUE</th><th>ACTIONS</th></tr></thead><tbody>{supplierPurchases.map(p=><tr key={p.id}><td>{dateText(p.date)}<button className="cell-sub table-action" onClick={()=>onOpen("purchase",p.id)}>{p.reference||p.id}</button></td><td>{p.items.map(i=><span key={i.id} className="tag-line">{i.name} × {i.quantity}</span>)}</td><td>{money(purchaseTotal(p)+purchaseExtraTotal(p))}</td><td>{money(p.paid)}</td><td>{money(purchaseDue(store,p))}</td><td><button className="table-action" onClick={()=>onPayment(p.id)}>Record payment</button></td></tr>)}</tbody></Table><h3>Payments received by this supplier</h3><Table><thead><tr><th>DATE</th><th>AMOUNT</th><th>FUNDED FROM</th><th>REFERENCE</th></tr></thead><tbody>{store.payments.filter(p=>p.kind==="Supplier payment"&&p.party===supplier.name).map(p=><tr key={p.id}><td>{dateText(p.date)}</td><td>{money(p.amount)}</td><td>{p.sourcePaymentId?store.payments.find(x=>x.id===p.sourcePaymentId)?.party||"Customer receipt":"General cash / bank"}</td><td>{p.reference}</td></tr>)}</tbody></Table></>}
 {purchase&&<><div className="ledger-summary"><div><span>Supplier</span><strong>{purchase.vendorName}</strong></div><div><span>Purchase budget</span><strong>{money(purchaseTotal(purchase)+purchaseExtraTotal(purchase))}</strong></div><div><span>Paid / due</span><strong>{money(purchase.paid)} / {money(purchaseDue(store,purchase))}</strong></div><div><span>Funding source</span><strong>{source?.party||"General cash / bank"}</strong></div></div><h3>Items and inventory lots</h3><Table><thead><tr><th>PRODUCT / VENDOR</th><th>RECEIVED</th><th>ON HAND</th><th>IN PROCESS</th><th>UNIT COST</th></tr></thead><tbody>{store.batches.filter(b=>b.purchaseId===purchase.id).map(b=><tr key={b.id}><td>{b.product}<span className="cell-sub">{b.vendorName} · {b.sku||b.id}</span></td><td>{b.quantity}</td><td>{b.remaining}</td><td>{processQuantity(b)}</td><td>{money(b.materialCost+b.manufacturingCost)}</td></tr>)}</tbody></Table><h3>Supplier payment installments</h3><Table><thead><tr><th>DATE</th><th>AMOUNT</th><th>RECEIPT SOURCE</th><th>REFERENCE</th></tr></thead><tbody>{payments.map(p=><tr key={p.id}><td>{dateText(p.date)}</td><td>{money(p.amount)}</td><td>{source?.party||"General cash / bank"}</td><td>{p.reference}</td></tr>)}</tbody></Table><h3>Other costs and return history</h3>{(purchase.extraExpenses??[]).map(e=><p key={e.id}>{e.category} · {e.payee} · {e.description} · {money(e.amount)}</p>)}{store.returns.filter(r=>r.purchaseId===purchase.id).map(r=><p key={r.id}>{dateText(r.date)} · returned {r.product} × {r.quantity} · {money(r.amount)} · {r.disposition}</p>)}</>}
 {detail.kind==="product"&&<><h2>Product history by supplier</h2><Table><thead><tr><th>SUPPLIER / PURCHASE</th><th>RECEIVED</th><th>IN</th><th>ON HAND</th><th>IN PROCESS</th><th>UNIT COST</th></tr></thead><tbody>{batches.map(b=><tr key={b.id}><td>{b.vendorName}<span className="cell-sub">{b.purchaseId} · {b.sku||b.id}</span></td><td>{dateText(b.received)}</td><td>{b.quantity}</td><td>{b.remaining}</td><td>{processQuantity(b)}</td><td>{money(b.materialCost+b.manufacturingCost)}</td></tr>)}</tbody></Table>{batches.flatMap(b=>(b.processes??[]).map(proc=><p key={proc.id}>{dateText(proc.date)} · {proc.quantity} units to {proc.process} · {proc.status} · {b.vendorName}</p>))}</>}
 {detail.kind==="customer"&&<><div className="ledger-summary"><div><span>Orders</span><strong>{orders.length}</strong></div><div><span>Sales total</span><strong>{money(orders.reduce((s,o)=>s+saleTotal(o),0))}</strong></div><div><span>Paid</span><strong>{money(orders.reduce((s,o)=>s+o.paid,0))}</strong></div><div><span>Balance due</span><strong>{money(orders.reduce((s,o)=>s+Math.max(0,saleTotal(o)-o.paid),0))}</strong></div></div><h3>Orders and invoices</h3><Table><thead><tr><th>DATE / ORDER</th><th>ITEMS</th><th>TOTAL</th><th>PAID / DUE</th><th>INVOICE</th></tr></thead><tbody>{orders.map(o=><tr key={o.id}><td>{dateText(o.created)}<span className="cell-sub">{o.id}</span></td><td>{o.items.map(i=><span key={i.id} className="tag-line">{i.product} × {i.quantity}</span>)}</td><td>{money(saleTotal(o))}</td><td>{money(o.paid)} / {money(Math.max(0,saleTotal(o)-o.paid))}</td><td>{o.invoice?<button className="table-action" onClick={()=>onInvoice(o.id)}>{o.invoice}</button>:"Not generated"}</td></tr>)}</tbody></Table><h3>Receipt installments</h3><Table><thead><tr><th>DATE</th><th>AMOUNT</th><th>METHOD</th><th>REFERENCE</th></tr></thead><tbody>{customerReceipts.map(p=><tr key={p.id}><td>{dateText(p.date)}</td><td>{money(p.amount)}</td><td>{p.method}</td><td>{p.reference}</td></tr>)}</tbody></Table></>}
 {expense&&<><div className="ledger-summary"><div><span>Amount</span><strong>{money(expense.amount)}</strong></div><div><span>Paid to</span><strong>{expense.payee}</strong></div><div><span>Category</span><strong>{expense.category}</strong></div><div><span>Date</span><strong>{dateText(expense.date)}</strong></div></div><p>{expense.description}</p><p>Funded from: {expense.sourcePaymentId?store.payments.find(p=>p.id===expense.sourcePaymentId)?.party||"Customer receipt":"General cash / bank"}</p></>}
 {receipt&&<><div className="ledger-summary"><div><span>{receipt.kind}</span><strong>{receipt.party}</strong></div><div><span>Amount</span><strong>{money(receipt.amount)}</strong></div><div><span>Method / date</span><strong>{receipt.method} · {dateText(receipt.date)}</strong></div><div><span>Funded from</span><strong>{receipt.sourcePaymentId?store.payments.find(p=>p.id===receipt.sourcePaymentId)?.party||"Customer receipt":"Customer funds / general cash"}</strong></div></div>{receipt.kind==="Customer receipt"&&<><h3>How this receipt was assigned</h3><Table><thead><tr><th>DATE</th><th>TYPE</th><th>PAID TO</th><th>AMOUNT ALLOCATED</th><th>STATUS</th></tr></thead><tbody>{store.purchases.filter(p=>p.sourcePaymentId===receipt.id).map(p=><tr key={p.id}><td>{dateText(p.date)}</td><td>Supplier purchase</td><td>{p.vendorName}</td><td>{money(purchaseTotal(p)+purchaseExtraTotal(p))}</td><td>{money(p.paid)} paid · {money(purchaseDue(store,p))} due</td></tr>)}{store.expenses.filter(e=>e.sourcePaymentId===receipt.id).map(e=><tr key={e.id}><td>{dateText(e.date)}</td><td>{e.category}</td><td>{e.payee}</td><td>{money(e.amount)}</td><td>{e.description}</td></tr>)}</tbody></Table><p>Unassigned balance: {money(Math.max(0,receipt.amount-receiptAllocated(store,receipt.id)))}</p></>}</>}
 </section>;
}

export default function Dashboard() {
  const [section, setSection] = useState<Section>("Overview");
  const [store, setStore] = useState<Store>(EMPTY);
  const [ready, setReady] = useState(false);
  const [search, setSearch] = useState("");
  const [from, setFrom] = useState("");
  const [to, setTo] = useState("");
  const [modal, setModal] = useState<Modal>(null);
  const [editId, setEditId] = useState("");
  const [editReturnId, setEditReturnId] = useState("");
  const [vendorContext, setVendorContext] = useState("");
  const [lineCount, setLineCount] = useState(1);
  const [purchaseExpenseCount,setPurchaseExpenseCount]=useState(1);
  const [purchaseView,setPurchaseView]=useState<"Purchases"|"Returns">("Purchases");
  const [selectedInvoices,setSelectedInvoices]=useState<string[]>([]);
  const [processType,setProcessType]=useState("Packing");
  const [continueToPurchase, setContinueToPurchase] = useState(false);
  const [mobileNav, setMobileNav] = useState(false);
  const [message, setMessage] = useState("");
  const [lowOnly, setLowOnly] = useState(false);
  const [refundReturnId, setRefundReturnId] = useState("");
  const [cashFlowFilter,setCashFlowFilter]=useState<CashFlowFilter>("All activity");
  const [cashSourceFilter,setCashSourceFilter]=useState("");
  const [detailView,setDetailView]=useState<DetailView|null>(null);

  useEffect(() => {
    try {
      let saved = localStorage.getItem(STORE_KEY);
      if (!saved) saved = localStorage.getItem(PREVIOUS_KEY);
      if (saved) setStore(migratePrevious(JSON.parse(saved)));
    } catch { setStore(EMPTY); }
    setReady(true);
  }, []);
  useEffect(() => { if (ready) localStorage.setItem(STORE_KEY, JSON.stringify(store)); }, [store, ready]);
  function log(next: Store, action: string, record: string, detail: string): Store {
    return { ...next, logs: [{ id: id("LOG"), dateTime: new Date().toISOString(), actor: "Admin", action, record, detail }, ...next.logs] };
  }
  function notify(text: string) { setMessage(text); window.setTimeout(() => setMessage(current => current === text ? "" : current), 5000); }
  function open(sectionName: Section) { setDetailView(null);setSection(sectionName); setMobileNav(false); setSearch(""); }
  function openDetail(kind:DetailView["kind"],recordId:string,home:Section){setDetailView({kind,id:recordId});setSection(home);setMobileNav(false);setSearch("");}
  function startPurchase() {
    if(store.vendors.length===0){setContinueToPurchase(true);open("Vendors");showModal("vendor");notify("Add this supplier once. Next, the purchase form will open and you can add all of their product lines.");return;}
    setContinueToPurchase(false);open("Purchases");showModal("purchase");
  }
  const inRange = (date: string) => (!from || date.slice(0, 10) >= from) && (!to || date.slice(0, 10) <= to);
  const queryMatches = (text: string) => text.toLowerCase().includes(search.trim().toLowerCase());

  const vendors = useMemo(() => store.vendors.filter(vendor => inRange(vendor.createdAt) && queryMatches(`${vendor.name} ${vendor.phone} ${vendor.email} ${vendor.products.map(p => `${p.name} ${p.sku}`).join(" ")}`)), [store.vendors, from, to, search]);
  const purchases = useMemo(() => store.purchases.filter(p => inRange(p.date) && queryMatches(`${p.id} ${p.vendorName} ${p.reference} ${p.items.map(x => `${x.name} ${x.sku}`).join(" ")}`)), [store.purchases, from, to, search]);
  const batches = useMemo(() => store.batches.filter(b => inRange(b.received) && queryMatches(`${b.id} ${b.product} ${b.sku} ${b.category} ${b.vendorName} ${b.warehouse}`) && (!lowOnly || (b.remaining > 0 && b.remaining <= 20))), [store.batches, from, to, search, lowOnly]);
  const orders = useMemo(() => store.orders.filter(o => inRange(o.created) && queryMatches(`${o.id} ${o.invoice ?? ""} ${o.customer} ${o.channel} ${o.items.map(x => x.product).join(" ")} ${o.status}`)), [store.orders, from, to, search]);
  const cashRows = useMemo(() => store.payments.filter(p => inRange(p.date) && queryMatches(`${p.id} ${p.kind} ${p.party} ${p.reference} ${p.method}`)), [store.payments, from, to, search]);
  const logs = useMemo(() => store.logs.filter(item => inRange(item.dateTime) && queryMatches(`${item.actor} ${item.action} ${item.record} ${item.detail}`)), [store.logs, from, to, search]);
  const expenses = useMemo(()=>store.expenses.filter(item=>inRange(item.date)&&queryMatches(`${item.date} ${item.category} ${item.payee} ${item.description} ${item.reference}`)),[store.expenses,from,to,search]);
  const expenseRows=[...store.purchases.flatMap(p=>[{id:p.id+"-goods",date:p.date,category:"Inventory purchase",payee:p.vendorName,description:p.items.map(i=>i.name+" × "+i.quantity).join(", "),amount:purchaseTotal(p),reference:p.reference||p.id,source:"Purchase",editable:false as const},...(p.extraExpenses??[]).map(item=>({id:item.id,date:p.date,category:item.category,payee:item.payee||p.vendorName,description:item.description,amount:item.amount,reference:p.id,source:"Purchase expense",editable:false as const}))]),...store.expenses.map(item=>({id:item.id,date:item.date,category:item.category,payee:item.payee||"Owner",description:item.description,amount:item.amount,reference:item.reference,source:"Expense",editable:true as const}))].filter(item=>inRange(item.date)&&queryMatches(`${item.date} ${item.category} ${item.payee} ${item.description} ${item.reference}`)).sort((a,b)=>b.date.localeCompare(a.date));
  const todayExpenseTotal=expenseRows.filter(item=>item.date===isoDate()).reduce((sum,item)=>sum+item.amount,0);

  const available = batchesFor(store, undefined).reduce((sum, batch) => sum + sellableQuantity(batch), 0);
  const inventoryValue = batchesFor(store, undefined).reduce((sum, batch) => sum + batch.remaining * (batch.materialCost + batch.manufacturingCost), 0);
  const saleValue = store.orders.filter(o => o.status !== "Draft" && inRange(o.created)).reduce((sum, o) => sum + saleTotal(o), 0);
  const taxableSales = store.orders.filter(o=>o.status!=="Draft"&&inRange(o.created)).reduce((sum,o)=>sum+saleSubtotal(o),0);
  const saleCogs = store.orders.filter(o => o.status !== "Draft" && inRange(o.created)).reduce((sum, o) => sum + saleCost(o), 0);
  const cashIn = store.payments.filter(p => p.kind === "Customer receipt" || p.kind === "Supplier refund").filter(p => inRange(p.date)).reduce((sum, p) => sum + p.amount, 0);
  const purchaseAdditionalExpenses=store.purchases.filter(p=>inRange(p.date)).reduce((sum,p)=>sum+purchaseExtraTotal(p),0);
  const operatingExpenses=store.expenses.filter(item=>inRange(item.date)).reduce((sum,item)=>sum+item.amount,0);
  const purchaseAmount=store.purchases.filter(p=>inRange(p.date)).reduce((sum,p)=>sum+purchaseTotal(p),0);
  const cashOut = store.payments.filter(p => p.kind === "Supplier payment" && inRange(p.date)).reduce((sum, p) => sum + p.amount, 0)+purchaseAdditionalExpenses+operatingExpenses;
  const totalDue = store.purchases.reduce((sum, p) => sum + purchaseDue(store, p), 0);
  const totalRefundDue = store.returns.reduce((sum, r) => sum + (r.disposition === "Refund due" ? r.amount - r.refunded : 0), 0);
  const totalReceivable = store.orders.reduce((sum, o) => sum + (o.invoice ? saleTotal(o) - o.paid : 0), 0);
  const totalExpenseAmount=purchaseAdditionalExpenses+operatingExpenses;
  const periodProfit=taxableSales-saleCogs-totalExpenseAmount;
  const ageReminders=store.batches.map(batch=>({...batch,age:daysOld(batch.received)})).filter(batch=>batch.remaining>0&&batch.age>=30).sort((a,b)=>b.age-a.age);
  const invoiceOrders=store.orders.filter(order=>order.status!=="Draft"&&inRange(order.created)&&queryMatches(`${order.customer} ${order.id} ${order.invoice??""} ${order.status}`));
  const dailyProfitPoints=makeDailyProfitPoints(store,from,to);
  const cashFlowRows:CashFlowRow[]=[
    ...store.payments.filter(p=>inRange(p.date)).map(p=>({id:p.id,date:p.date,kind:(p.kind==="Customer receipt"?"Customer receipts":p.kind==="Supplier refund"?"Supplier refunds":"Supplier payments") as CashFlowRow["kind"],party:p.party,reference:p.reference||p.id,amount:p.amount,sourcePaymentId:p.sourcePaymentId,sourceName:p.sourcePaymentId?store.payments.find(source=>source.id===p.sourcePaymentId)?.party||"Customer receipt":p.kind==="Customer receipt"?"Customer payment":"General cash / bank",status:p.kind==="Customer receipt"?"Money received":"Money paid",detailKind:"payment" as const})),
    ...store.purchases.filter(p=>inRange(p.date)).map(p=>({id:p.id,date:p.date,kind:"Purchases" as const,party:p.vendorName,reference:p.reference||p.id,amount:purchaseTotal(p)+purchaseExtraTotal(p),sourcePaymentId:p.sourcePaymentId,sourceName:p.sourcePaymentId?store.payments.find(source=>source.id===p.sourcePaymentId)?.party||"Customer receipt":"General cash / bank",status:`${money(p.paid)} paid · ${money(purchaseDue(store,p))} due`,detailKind:"purchase" as const})),
    ...store.expenses.filter(e=>inRange(e.date)).map(e=>({id:e.id,date:e.date,kind:"Other expenses" as const,party:e.payee||"Owner",reference:e.description||e.reference,amount:e.amount,sourcePaymentId:e.sourcePaymentId,sourceName:e.sourcePaymentId?store.payments.find(source=>source.id===e.sourcePaymentId)?.party||"Customer receipt":"General cash / bank",status:"Recorded expense",detailKind:"expense" as const})),
    ...store.purchases.filter(p=>inRange(p.date)).flatMap(p=>(p.extraExpenses??[]).map(e=>({id:e.id,date:p.date,kind:"Other expenses" as const,party:e.payee||p.vendorName,reference:e.description,amount:e.amount,sourcePaymentId:p.sourcePaymentId,sourceName:p.sourcePaymentId?store.payments.find(source=>source.id===p.sourcePaymentId)?.party||"Customer receipt":"General cash / bank",status:`Included in purchase ${p.id}`,detailKind:"purchase" as const})))
  ].filter(row=>cashFlowFilter==="All activity"||(cashFlowFilter==="Customer receipts"?row.kind==="Customer receipts"||row.kind==="Supplier refunds":row.kind===cashFlowFilter)).filter(row=>!cashSourceFilter||row.id===cashSourceFilter||row.sourcePaymentId===cashSourceFilter).filter(row=>queryMatches(`${row.date} ${row.kind} ${row.party} ${row.reference} ${row.sourceName}`)).sort((a,b)=>b.date.localeCompare(a.date));
  const selectedCashReceipt=store.payments.find(p=>p.id===cashSourceFilter&&p.kind==="Customer receipt");
  const selectedReceiptPurchases=selectedCashReceipt?store.purchases.filter(p=>p.sourcePaymentId===selectedCashReceipt.id):[];
  const selectedReceiptExpenses=selectedCashReceipt?store.expenses.filter(e=>e.sourcePaymentId===selectedCashReceipt.id):[];
  const selectedSupplierPaid=selectedCashReceipt?store.payments.filter(p=>p.kind==="Supplier payment"&&p.sourcePaymentId===selectedCashReceipt.id).reduce((sum,p)=>sum+p.amount,0):0;
  const selectedActualSpent=selectedSupplierPaid+selectedReceiptExpenses.reduce((sum,e)=>sum+e.amount,0)+selectedReceiptPurchases.reduce((sum,p)=>sum+purchaseExtraTotal(p),0);
  const selectedReceiptBudget=selectedReceiptPurchases.reduce((sum,p)=>sum+purchaseTotal(p)+purchaseExtraTotal(p),0);
  const selectedOrder = store.orders.find(o => o.id === editId);
  const selectedReturn = store.returns.find(r => r.id === refundReturnId);
  const title = section === "Overview" ? "Business overview" : section;
  const description: Record<Section, string> = {
    "Overview": "Purchases, inventory, sales, invoices and cash flow in one place.",
    "Inventory": "Search stock lots, filter by received date, and return items to the vendor that supplied them.",
    "Vendors": "Maintain each supplier once and keep a separate product catalog for each one.",
    "Purchases": "Record multi-product purchases, edit or return a line, and track supplier balances.",
    "Sales": "Create orders from available stock, confirm, generate invoices and record receipts.",
    "Invoices": "Select completed sales and generate customer invoices in one step.",
    "Today's expenses": "Record and review supplier purchase costs, staff payments, and daily operating expenses.",
    "Cash flow": "Customer receipts, supplier payments and supplier refunds with current balances.",
    "Reports": "Review purchases, sales, returns, margins and cash movements for a date range.",
    "Activity log": "Timestamped history of purchase, product, supplier, order and payment changes.",
    "Profile": "Company details are used in the From section of every generated sales invoice.",
  };

  function showModal(type: Modal, target = "") { setEditId(target); setEditReturnId("");setModal(type); const purchase=store.purchases.find(item=>item.id===target);const order=store.orders.find(item=>item.id===target);setLineCount(type==="purchase"&&purchase?purchase.items.length:type==="order"&&order?order.items.length:1);setPurchaseExpenseCount(type==="purchase"&&purchase?Math.max(1,purchase.extraExpenses?.length??0):1); }

  function saveVendor(form: FormData, editing?: Vendor) {
    const name = String(form.get("name") ?? "").trim();
    if (!name) return;
    if (store.vendors.some(v => v.id !== editing?.id && v.name.toLowerCase() === name.toLowerCase())) { notify("A supplier with that name already exists. Open the existing supplier instead."); return; }
    const vendor: Vendor = { ...(editing ?? newVendor(name)), name, phone: String(form.get("phone") ?? ""), email: String(form.get("email") ?? ""), address: String(form.get("address") ?? ""), bank: String(form.get("bank") ?? ""), accountName: String(form.get("accountName") ?? ""), accountNumber: String(form.get("accountNumber") ?? ""), ifsc: String(form.get("ifsc") ?? ""), products: editing?.products ?? [], createdAt: editing?.createdAt ?? isoDate() };
    setStore(current => log({ ...current, vendors: editing ? current.vendors.map(v => v.id === editing.id ? vendor : v) : [vendor, ...current.vendors], purchases: editing ? current.purchases.map(p=>p.vendorId===editing.id?{...p,vendorName:vendor.name}:p) : current.purchases, batches: editing ? current.batches.map(b=>b.vendorId===editing.id?{...b,vendorName:vendor.name}:b) : current.batches, returns: editing ? current.returns.map(r=>r.vendorId===editing.id?{...r,vendorName:vendor.name}:r) : current.returns, payments: editing ? current.payments.map(p=>p.party===editing.name?{...p,party:vendor.name}:p) : current.payments }, editing ? "Edited supplier profile" : "Created supplier", vendor.name, `${vendor.phone} ${vendor.email}`.trim()));
    if(continueToPurchase&&!editing){setContinueToPurchase(false);setSection("Purchases");showModal("purchase");notify(`${vendor.name} is saved. Add every product from this supplier to the purchase now.`);return;}
    setModal(null); notify(`${vendor.name} ${editing ? "updated" : "added to your supplier list"}.`);
  }

  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const form = new FormData(event.currentTarget);
    if(modal==="expense"||modal==="edit-expense"){
      const oldExpense=modal==="edit-expense"?store.expenses.find(item=>item.id===editId):undefined;
      const amount=Number(form.get("amount"));const sourcePaymentId=String(form.get("sourcePaymentId")??"");
      if(!amount||amount<=0){notify("Enter an expense amount greater than zero.");return;}
      if(sourcePaymentId){const receipt=store.payments.find(item=>item.id===sourcePaymentId&&item.kind==="Customer receipt");const allocated=receiptAllocated(store,sourcePaymentId,"",oldExpense?.id??"");if(!receipt||amount>receipt.amount-allocated){notify("This expense is higher than the remaining amount from the selected customer receipt.");return;}}
      const expense:Expense={id:oldExpense?.id??id("EXP"),date:String(form.get("date")??isoDate()),category:String(form.get("category")??"Other"),payee:String(form.get("payee")??"").trim(),description:String(form.get("description")??"").trim(),amount,method:String(form.get("method")??"Cash"),reference:String(form.get("reference")??"").trim(),sourcePaymentId:sourcePaymentId||undefined};
      setStore(current=>log({...current,expenses:oldExpense?current.expenses.map(item=>item.id===oldExpense.id?expense:item):[expense,...current.expenses]},oldExpense?"Edited expense":"Recorded expense",expense.id,`${expense.category} · ${expense.description} · ${money(expense.amount)}${sourcePaymentId?" · linked to customer receipt":""}`));setModal(null);notify(`${oldExpense?"Expense updated":"Expense recorded"}. Cash flow and expense reports were updated.`);return;
    }
    if(modal==="process"){
      const batch=store.batches.find(item=>item.id===editId);if(!batch)return;
      const process=String(form.get("process")??"").trim();const quantity=Number(form.get("quantity"));
      const inProcess=(batch.processes??[]).filter(item=>item.status==="In process").reduce((sum,item)=>sum+item.quantity,0);
      const free=batch.remaining;
      if(!process||quantity<1||quantity>free){notify(`Enter a quantity from 1 to ${Math.max(0,free)} units available for processing.`);return;}
      const entry:ProcessEntry={id:id("PRC"),process,quantity,date:String(form.get("date")??isoDate()),status:"In process",note:String(form.get("note")??"").trim()};
      setStore(current=>log({...current,batches:current.batches.map(item=>item.id===batch.id?{...item,remaining:item.remaining-quantity,processes:[...(item.processes??[]),entry]}:item)},"Sent stock to process",`${batch.vendorName} / ${batch.product}`,`${quantity} units · ${process}`));setModal(null);notify(`${quantity} units moved to ${process}. On-hand stock was reduced.`);return;
    }
    if (modal === "vendor") { saveVendor(form, store.vendors.find(v => v.id === editId)); return; }
    if (modal === "product") {
      const vendor = store.vendors.find(v => v.id === editId); if (!vendor) return;
      const name = String(form.get("name") ?? "").trim(); const sku = String(form.get("sku") ?? "").trim();
      if (!name) return;
      if (vendor.products.some(p => p.id !== vendorContext && p.name.toLowerCase() === name.toLowerCase())) { notify("This supplier already has a product with that name."); return; }
      const product: VendorProduct = { id: vendorContext || id("SKU"), name, sku, category: String(form.get("category") ?? "Other") };
      setStore(current => log({ ...current, vendors: current.vendors.map(item => item.id === vendor.id ? { ...item, products: vendorContext ? item.products.map(p => p.id === vendorContext ? product : p) : [product, ...item.products] } : item) }, vendorContext ? "Edited supplier product" : "Added supplier product", `${vendor.name} / ${product.name}`, sku));
      setModal(null); setVendorContext(""); notify(`${product.name} saved under ${vendor.name}.`); return;
    }
    if (modal === "purchase") {
      const vendorId = String(form.get("vendorId") ?? ""); const vendor = store.vendors.find(v => v.id === vendorId); if (!vendor) { notify("Choose a supplier before saving this purchase."); return; }
      const items: PurchaseLine[] = [];
      const extraExpenses:PurchaseExpense[]=[];
      for(let index=0;index<purchaseExpenseCount;index++){const description=String(form.get(`extra-description-${index}`)??"").trim();const amount=Number(form.get(`extra-amount-${index}`));if((description&&amount<=0)||(!description&&amount>0)){notify("For each extra cost, enter both a description and an amount.");return;}if(description&&amount>0)extraExpenses.push({id:id("PEX"),description,category:String(form.get(`extra-category-${index}`)??"Other"),amount,payee:String(form.get(`extra-payee-${index}`)??"").trim()});}
      for (let index = 0; index < lineCount; index++) {
        const name = String(form.get(`product-${index}`) ?? "").trim(); if (!name) continue;
        const existing = vendor.products.find(p => p.name.toLowerCase() === name.toLowerCase());
        const product: VendorProduct = existing ?? { id: id("SKU"), name, sku: String(form.get(`sku-${index}`) ?? "").trim(), category: String(form.get(`category-${index}`) ?? "Other") };
        if (items.some(item => item.productId === product.id)) { notify("A purchase can include a supplier product only once. Increase that line’s quantity instead."); return; }
        items.push({ id: id("ITM"), productId: product.id, name: product.name, sku: String(form.get(`sku-${index}`) || product.sku), category: String(form.get(`category-${index}`) || product.category), quantity: Number(form.get(`quantity-${index}`)), materialCost: Number(form.get(`unit-cost-${index}`)), manufacturingCost: 0, returned: 0 });
      }
      if (!items.length || items.some(item => !item.quantity || item.quantity < 1 || !Number.isFinite(item.materialCost) || item.materialCost < 0)) { notify("Add at least one product with a valid quantity."); return; }
      const purchaseId = editId || id("PUR"); const old = store.purchases.find(p => p.id === purchaseId);
      const sourcePaymentId=String(form.get("sourcePaymentId")??"");
      const fundingBudget=items.reduce((sum,item)=>sum+lineTotal(item),0)+extraExpenses.reduce((sum,item)=>sum+item.amount,0);
      if(sourcePaymentId){const receipt=store.payments.find(p=>p.id===sourcePaymentId&&p.kind==="Customer receipt");const available=receipt?receipt.amount-receiptAllocated(store,sourcePaymentId,old?.id??""):0;if(!receipt||fundingBudget>available){notify(`${vendor.name} purchase budget is ${money(fundingBudget)}; only ${money(Math.max(0,available))} remains from the selected customer receipt.`);return;}}
      if (old) {
        if(old.vendorId!==vendor.id&&(old.paid>0||store.returns.some(item=>item.purchaseId===old.id))){notify("A supplier cannot be changed after payments or returns have been recorded.");return;}
        if(old.paid>0&&old.sourcePaymentId!==sourcePaymentId){notify("This purchase already has supplier payments. Keep its original funding source so the cash trail stays accurate.");return;}
        const refreshedItems = items.map(item => { const previous = old.items.find(p => p.productId === item.productId); return previous ? { ...item, id: previous.id, returned: previous.returned } : item; });
        for (const previous of old.items) {
          const priorBatch = store.batches.find(b => b.purchaseId === old.id && b.lineId === previous.id);
          const nextLine = refreshedItems.find(i => i.id === previous.id);
          const inProcess=priorBatch?processQuantity(priorBatch):0;
          const soldOrReturned = previous.quantity - (priorBatch?.remaining ?? 0) - previous.returned - inProcess;
          if (!nextLine && (soldOrReturned > 0 || previous.returned > 0 || inProcess>0)) { notify(`Cannot remove ${previous.name}; units are sold, returned, or currently in process.`); return; }
          if (nextLine && nextLine.quantity < soldOrReturned + previous.returned + inProcess) { notify(`Quantity for ${previous.name} cannot be lower than sold, returned, or in-process units.`); return; }
        }
        const nextPurchase: Purchase = { ...old, vendorId: vendor.id, vendorName: vendor.name, reference: String(form.get("reference") ?? ""), date: String(form.get("date") ?? old.date), items: refreshedItems, extraExpenses, sourcePaymentId:sourcePaymentId||undefined };
        const removedLineIds = old.items.filter(previous=>!refreshedItems.some(item=>item.id===previous.id)).map(item=>item.id);
        const nextBatches = store.batches.filter(batch=>!(batch.purchaseId===old.id&&removedLineIds.includes(batch.lineId)));
        for (const item of refreshedItems) {
          const batch = nextBatches.find(b => b.purchaseId === old.id && b.lineId === item.id);
          if (batch) { const previous = old.items.find(p => p.id === item.id)!; const processing=processQuantity(batch); const sold = previous.quantity - batch.remaining - previous.returned - processing; batch.vendorId=vendor.id; batch.vendorName=vendor.name; batch.productId=item.productId; batch.product=item.name; batch.sku=item.sku; batch.category=item.category; batch.quantity = item.quantity; batch.remaining = item.quantity - sold - item.returned - processing; batch.materialCost = item.materialCost; batch.manufacturingCost = item.manufacturingCost; }
          else nextBatches.unshift({ id: id("LOT"), purchaseId: old.id, lineId: item.id, vendorId: vendor.id, vendorName: vendor.name, productId: item.productId, product: item.name, sku: item.sku, category: item.category, received: nextPurchase.date, quantity: item.quantity, remaining: item.quantity, materialCost: item.materialCost, manufacturingCost: item.manufacturingCost, warehouse: String(form.get("warehouse") ?? "Warehouse A") });
        }
        const productAdds = items.filter(item => !vendor.products.some(p => p.id === item.productId)).map(item => ({ id: item.productId, name: item.name, sku: item.sku, category: item.category }));
        setStore(current => log({ ...current, vendors: current.vendors.map(v => v.id === vendor.id ? { ...v, products: [...productAdds, ...v.products] } : v), purchases: current.purchases.map(p => p.id === old.id ? nextPurchase : p), batches: nextBatches }, "Edited purchase", old.id, `${vendor.name} · ${items.length} products`));
        setModal(null); notify(`Purchase ${old.id} updated. Inventory quantities and costs were adjusted.`); return;
      }
      const date = String(form.get("date") ?? isoDate());
      const purchase: Purchase = { id: purchaseId, vendorId: vendor.id, vendorName: vendor.name, reference: String(form.get("reference") ?? "").trim(), date, paid: 0, items, extraExpenses, sourcePaymentId:sourcePaymentId||undefined };
      const newProducts = items.filter(item => !vendor.products.some(p => p.id === item.productId)).map(item => ({ id: item.productId, name: item.name, sku: item.sku, category: item.category }));
      const newBatches = items.map(item => ({ id: id("LOT"), purchaseId, lineId: item.id, vendorId: vendor.id, vendorName: vendor.name, productId: item.productId, product: item.name, sku: item.sku, category: item.category, received: date, quantity: item.quantity, remaining: item.quantity, materialCost: item.materialCost, manufacturingCost: item.manufacturingCost, warehouse: String(form.get("warehouse") ?? "Warehouse A") }));
      setStore(current => log({ ...current, vendors: current.vendors.map(v => v.id === vendor.id ? { ...v, products: [...newProducts, ...v.products] } : v), purchases: [purchase, ...current.purchases], batches: [...newBatches, ...current.batches] }, "Created purchase and received stock", purchase.id, `${vendor.name} · ${items.length} product lines · ${money(purchaseTotal(purchase))}`));
      setModal(null); notify(`Purchase recorded for ${vendor.name}. ${items.length} product lots were added to inventory.`); return;
    }
    if (modal === "purchase-return") {
      const oldReturn=store.returns.find(item=>item.id===editReturnId);
      const purchase = store.purchases.find(p => p.id === (oldReturn?.purchaseId??editId)); if (!purchase) return;
      const lineId=String(form.get("lineId"));
      if(oldReturn&&lineId!==oldReturn.lineId){notify("Edit the same product lot on this return. Delete and recreate it only if no refund has been received.");return;}
      const line = purchase.items.find(item => item.id === lineId); if (!line) return;
      const quantity = Number(form.get("quantity"));
      const disposition=String(form.get("disposition")) as PurchaseReturn["disposition"];
      const returnValue=quantity*(line.materialCost+line.manufacturingCost);
      if(oldReturn&&returnValue<oldReturn.refunded){notify("The return value cannot be lower than the refund already received.");return;}
      if(oldReturn&&oldReturn.refunded>0&&disposition!==oldReturn.disposition){notify("Settlement type cannot change after a refund has been received.");return;}
      if(disposition==="Refund due"){
        const otherRefunds=store.returns.filter(r=>r.purchaseId===purchase.id&&r.disposition==="Refund due"&&r.id!==oldReturn?.id).reduce((sum,r)=>sum+r.amount,0);
        if(purchase.paid<otherRefunds+returnValue){notify("The supplier has not paid enough on this purchase to owe this refund. Choose Vendor credit or return fewer units.");return;}
      }
      const updatedBatches=store.batches.map(batch=>({...batch}));
      if(oldReturn){let restore=oldReturn.quantity;for(const batch of updatedBatches.filter(b=>b.purchaseId===purchase.id&&b.lineId===line.id)){batch.remaining+=restore;restore=0;break;}}
      const availableToReturn=updatedBatches.filter(b=>b.purchaseId===purchase.id&&b.lineId===line.id).reduce((sum,b)=>sum+b.remaining,0);
      if(!quantity||quantity>availableToReturn){notify(`Only ${availableToReturn} unreserved units from this vendor lot can be returned.`);return;}
      let remove=quantity;for(const batch of updatedBatches.filter(b=>b.purchaseId===purchase.id&&b.lineId===line.id).reverse()){const take=Math.min(remove,batch.remaining);batch.remaining-=take;remove-=take;if(!remove)break;}
      const returned:PurchaseReturn={id:oldReturn?.id??id("RET"),purchaseId:purchase.id,vendorId:purchase.vendorId,vendorName:purchase.vendorName,lineId:line.id,productId:line.productId,product:line.name,quantity,amount:returnValue,disposition,refunded:oldReturn?.refunded??0,reason:String(form.get("reason")??"").trim(),date:String(form.get("date")??isoDate())};
      const updatedPurchase={...purchase,items:purchase.items.map(item=>item.id===line.id?{...item,returned:item.returned-(oldReturn?.quantity??0)+quantity}:item)};
      const nextReturns=oldReturn?store.returns.map(item=>item.id===oldReturn.id?returned:item):[returned,...store.returns];
      setStore(current=>log({...current,batches:updatedBatches,purchases:current.purchases.map(p=>p.id===purchase.id?updatedPurchase:p),returns:nextReturns},oldReturn?"Edited purchase return":"Returned purchased stock",`${returned.vendorName} / ${returned.product}`,`${quantity} units · ${returned.disposition} · ${money(returned.amount)}`));
      setModal(null);setEditReturnId("");notify(`${oldReturn?"Return updated":"Return recorded"} against ${purchase.vendorName}. The correct inventory lot and balances were adjusted.`);return;
    }
    if (modal === "order") {
      const customer = String(form.get("customer") ?? "").trim(); const saleLines: SaleLine[] = [];
      for (let index = 0; index < lineCount; index++) {
        const productId = String(form.get(`product-${index}`) ?? ""); if (!productId) continue;
        const product = store.vendors.flatMap(v => v.products).find(p => p.id === productId); if (!product) continue;
        saleLines.push({ id: id("SLI"), productId, product: product.name, quantity: Number(form.get(`quantity-${index}`)), price: Number(form.get(`price-${index}`)), taxRate: Number(form.get(`tax-${index}`)) || 0, cogs: 0, allocations: [] });
      }
      if (!customer || !saleLines.length || saleLines.some(item => !item.quantity || !item.price)) { notify("Add a customer and at least one valid order line."); return; }
      const old=store.orders.find(item=>item.id===editId);
      if(old){
        const nextOrder:Order={...old,customer,channel:String(form.get("channel")),created:String(form.get("date")??old.created),items:saleLines};
        if(old.paid>saleTotal(nextOrder)){notify("The updated order total cannot be lower than payments already collected.");return;}
        let nextBatches=store.batches.map(batch=>({...batch}));
        if(old.status!=="Draft"){
          old.items.forEach(line=>line.allocations.forEach(allocation=>{const batch=nextBatches.find(item=>item.id===allocation.batchId);if(batch)batch.remaining+=allocation.quantity;}));
          for(const line of nextOrder.items){let left=line.quantity;const lots=nextBatches.filter(batch=>batch.productId===line.productId&&sellableQuantity(batch)>0).sort((a,b)=>a.received.localeCompare(b.received));if(lots.reduce((sum,batch)=>sum+sellableQuantity(batch),0)<left){notify(`Not enough ${line.product} is available to save this edited order.`);return;}for(const batch of lots){if(!left)break;const take=Math.min(sellableQuantity(batch),left);batch.remaining-=take;left-=take;line.cogs+=take*(batch.materialCost+batch.manufacturingCost);line.allocations.push({batchId:batch.id,quantity:take});}}
        }
        setStore(current=>log({...current,batches:nextBatches,orders:current.orders.map(item=>item.id===old.id?nextOrder:item)},"Edited sales order",old.id,`${customer} · ${saleLines.length} products · ${money(saleTotal(nextOrder))}`));
        setModal(null);notify(`Sales order ${old.id} updated. Its stock allocations and FIFO costs were recalculated.`);return;
      }
      const order: Order = { id: id("ORD"), customer, channel: String(form.get("channel")), created: String(form.get("date") ?? isoDate()), status: "Draft", paid: 0, items: saleLines };
      setStore(current => log({ ...current, orders: [order, ...current.orders] }, "Created draft sales order", order.id, `${customer} · ${order.channel} · ${saleLines.length} items · ${money(saleTotal(order))}`));
      setModal(null); notify(`${order.id} saved as a draft. Confirm it from Sales to allocate stock.`); return;
    }
    if (modal === "supplier-payment" || modal === "customer-payment" || modal === "supplier-refund" || modal === "edit-payment") {
      const editing = modal === "edit-payment" ? store.payments.find(p => p.id === editId) : undefined;
      const kind = editing?.kind ?? (modal === "supplier-payment" ? "Supplier payment" : modal === "customer-payment" ? "Customer receipt" : "Supplier refund");
      const amount = Number(form.get("amount")); const method = String(form.get("method") ?? "Bank transfer");
      const linkId = editing?.linkId ?? String(form.get("target") ?? ""); const reference = String(form.get("reference") ?? "").trim();
      const delta = amount - (editing?.amount ?? 0);
      if (kind === "Supplier payment") {
        const purchase = store.purchases.find(p => p.id === linkId); if (!purchase || amount <= 0 || delta > purchaseDue(store, purchase) + (editing?.amount ?? 0)) { notify("Payment exceeds the supplier balance."); return; }
        const sourcePaymentId=purchase.sourcePaymentId||String(form.get("sourcePaymentId")??"");if(sourcePaymentId&&purchase.sourcePaymentId!==sourcePaymentId){const receipt=store.payments.find(p=>p.id===sourcePaymentId&&p.kind==="Customer receipt");const allocated=receiptAllocated(store,sourcePaymentId,"","",editing?.id??"");if(!receipt||amount>receipt.amount-allocated){notify("This supplier payment is more than the unassigned amount from that customer receipt.");return;}}
        const record: Payment = { id: editing?.id ?? id("PAY"), date: String(form.get("date") ?? isoDate()), kind, party: purchase.vendorName, reference: reference || purchase.id, method, amount, linkId, sourcePaymentId:sourcePaymentId||undefined };
        setStore(current => log({ ...current, purchases: current.purchases.map(p => p.id === linkId ? { ...p, paid: p.paid + delta } : p), payments: editing ? current.payments.map(p => p.id === editing.id ? record : p) : [record, ...current.payments] }, editing ? "Edited supplier payment" : "Recorded supplier payment", record.id, `${purchase.vendorName} · ${money(amount)} · ${method}`));
      } else if (kind === "Customer receipt") {
        const order = store.orders.find(o => o.id === linkId); if (!order || amount <= 0 || delta > saleTotal(order) - order.paid + (editing?.amount ?? 0)) { notify("Receipt exceeds the open invoice balance."); return; }
        const record: Payment = { id: editing?.id ?? id("REC"), date: String(form.get("date") ?? isoDate()), kind, party: order.customer, reference: reference || order.invoice || order.id, method, amount, linkId };
        setStore(current => log({ ...current, orders: current.orders.map(o => o.id === linkId ? { ...o, paid: o.paid + delta, status: o.paid + delta >= saleTotal(o) ? "Paid" : o.status } : o), payments: editing ? current.payments.map(p => p.id === editing.id ? record : p) : [record, ...current.payments] }, editing ? "Edited customer receipt" : "Received customer payment", record.id, `${order.customer} · ${money(amount)} · ${method}`));
      } else {
        const returned = store.returns.find(r => r.id === linkId); if (!returned || amount <= 0 || delta > returned.amount - returned.refunded + (editing?.amount ?? 0)) { notify("Refund exceeds the vendor refund balance."); return; }
        const record: Payment = { id: editing?.id ?? id("REF"), date: String(form.get("date") ?? isoDate()), kind: "Supplier refund", party: returned.vendorName, reference: reference || returned.id, method, amount, linkId };
        setStore(current => log({ ...current, returns: current.returns.map(r => r.id === linkId ? { ...r, refunded: r.refunded + delta } : r), payments: editing ? current.payments.map(p => p.id === editing.id ? record : p) : [record, ...current.payments] }, editing ? "Edited supplier refund receipt" : "Received supplier refund", record.id, `${returned.vendorName} · ${money(amount)} · ${method}`));
      }
      setModal(null); notify(`${editing ? "Payment updated" : "Payment recorded"}. Linked balances and the cash ledger are updated.`); return;
    }
    if (modal === null && section === "Profile") {
      const profile = Object.fromEntries(Object.keys(EMPTY_PROFILE).map(key => [key, String(form.get(key) ?? "").trim()])) as unknown as Profile;
      setStore(current => log({ ...current, profile }, "Updated company profile", profile.name, "Invoice From details and bank details saved")); notify("Company profile saved. New invoices will use these From details.");
    }
  }

  function confirmOrder(order: Order) {
    let workingBatches = store.batches.map(batch => ({ ...batch })); let lines = order.items.map(line => ({ ...line, allocations: [] as { batchId: string; quantity: number }[], cogs: 0 }));
    for (const line of lines) {
      let quantityLeft = line.quantity;
      const lots = workingBatches.filter(batch => batch.productId === line.productId && sellableQuantity(batch) > 0).sort((a, b) => a.received.localeCompare(b.received));
      if (lots.reduce((sum, batch) => sum + sellableQuantity(batch), 0) < quantityLeft) { notify(`Not enough ${line.product} is available. Check the Inventory tab.`); return; }
      for (const batch of lots) { if (!quantityLeft) break; const take = Math.min(sellableQuantity(batch), quantityLeft); batch.remaining -= take; quantityLeft -= take; line.cogs += take * (batch.materialCost + batch.manufacturingCost); line.allocations.push({ batchId: batch.id, quantity: take }); }
    }
    const nextOrder = { ...order, items: lines, status: "Confirmed" as const };
    setStore(current => log({ ...current, batches: workingBatches, orders: current.orders.map(item => item.id === order.id ? nextOrder : item) }, "Confirmed sales order", order.id, `${order.customer} · ${order.items.reduce((sum, item) => sum + item.quantity, 0)} units deducted FIFO`)); notify(`${order.id} confirmed. Inventory was deducted from the oldest lots.`);
  }

  function toggleInvoice(orderId:string,checked:boolean){setSelectedInvoices(current=>checked?[...new Set([...current,orderId])]:current.filter(id=>id!==orderId));}
  function generateSelectedInvoices(){
    const selected=invoiceOrders.filter(order=>selectedInvoices.includes(order.id));
    if(!selected.length){notify("Select at least one sales order first.");return;}
    const ready=selected.map(order=>order.invoice?order:{...order,invoice:`INV-${order.id.replace("ORD-","")}`,status:order.status==="Paid"?"Paid" as const:"Invoiced" as const});
    const newlyGenerated=ready.filter(order=>!selected.find(item=>item.id===order.id)?.invoice);
    if(newlyGenerated.length)setStore(current=>log({...current,orders:current.orders.map(order=>ready.find(item=>item.id===order.id)??order)},"Generated sales invoices",`${newlyGenerated.length} invoices`,newlyGenerated.map(order=>order.invoice).join(", ")));
    const blob=buildInvoicesPdf(ready,store.profile);const url=URL.createObjectURL(blob);const anchor=document.createElement("a");anchor.href=url;anchor.download=`D2Garments-Invoices-${isoDate()}.pdf`;document.body.appendChild(anchor);anchor.click();anchor.remove();window.setTimeout(()=>URL.revokeObjectURL(url),1000);
    setSelectedInvoices([]);notify(`${ready.length} invoice${ready.length===1?"":"s"} downloaded as one PDF${newlyGenerated.length?` and ${newlyGenerated.length} invoice number${newlyGenerated.length===1?" was":"s were"} created`:""}.`);
  }

  function saveProfile(event: FormEvent<HTMLFormElement>) { event.preventDefault(); submit(event); }

  function deletePurchase(purchase: Purchase) {
    if(store.batches.some(batch=>batch.purchaseId===purchase.id&&(batch.processes??[]).length>0)){notify("This purchase has stock process history. Keep it so the production trail remains traceable.");return;}
    if (purchase.paid || store.returns.some(r => r.purchaseId === purchase.id)) { notify("This purchase has payments or returns. Keep it in the audit trail and edit its remaining balance instead."); return; }
    const connected = store.batches.filter(b => b.purchaseId === purchase.id);
    if (connected.some(b => b.remaining !== b.quantity)) { notify("Stock from this purchase has already been sold or returned. It can’t be deleted safely."); return; }
    if (!window.confirm(`Delete purchase ${purchase.id} from ${purchase.vendorName}? Its untouched inventory lots will also be removed.`)) return;
    setStore(current => log({ ...current, purchases: current.purchases.filter(p => p.id !== purchase.id), batches: current.batches.filter(b => b.purchaseId !== purchase.id) }, "Deleted purchase", purchase.id, `${purchase.vendorName} · ${purchase.items.length} items`));
  }

  function deleteReturn(returned:PurchaseReturn) {
    if(returned.refunded>0){notify("A supplier refund has already been received. Keep this return in the audit trail and edit the linked refund instead.");return;}
    if(!window.confirm(`Delete return ${returned.id} for ${returned.product} to ${returned.vendorName}? The stock and supplier balance will be restored.`))return;
    const purchase=store.purchases.find(item=>item.id===returned.purchaseId);if(!purchase)return;
    const batches=store.batches.map(batch=>({...batch}));let remaining=returned.quantity;
    for(const batch of batches.filter(item=>item.purchaseId===returned.purchaseId&&item.lineId===returned.lineId)){const restore=Math.min(remaining,batch.quantity-batch.remaining);batch.remaining+=restore;remaining-=restore;if(!remaining)break;}
    const nextPurchase={...purchase,items:purchase.items.map(item=>item.id===returned.lineId?{...item,returned:Math.max(0,item.returned-returned.quantity)}:item)};
    setStore(current=>log({...current,batches,purchases:current.purchases.map(item=>item.id===purchase.id?nextPurchase:item),returns:current.returns.filter(item=>item.id!==returned.id)},"Deleted purchase return",returned.id,`${returned.vendorName} / ${returned.product} · ${returned.quantity} units restored`));
  }

  function deleteOrder(order: Order) {
    if (order.paid || store.payments.some(p => p.kind === "Customer receipt" && p.linkId === order.id)) { notify("This order has customer receipts. Keep it in the audit trail; reverse or edit the receipt first."); return; }
    if (!window.confirm(`Delete sales order ${order.id} for ${order.customer}?`)) return;
    const restored = store.batches.map(batch => ({ ...batch }));
    order.items.forEach(line => line.allocations.forEach(allocation => { const batch = restored.find(item => item.id === allocation.batchId); if (batch) batch.remaining += allocation.quantity; }));
    setStore(current => log({ ...current, batches: restored, orders: current.orders.filter(o => o.id !== order.id) }, "Deleted sales order", order.id, `${order.customer} · stock allocations restored`));
  }

  function deletePayment(payment: Payment) {
    if (!window.confirm(`Delete ${payment.kind.toLowerCase()} of ${money(payment.amount)} for ${payment.party}? The linked balance will be restored.`)) return;
    let next: Store = { ...store, payments: store.payments.filter(p => p.id !== payment.id) };
    if (payment.kind === "Supplier payment") next.purchases = next.purchases.map(p => p.id === payment.linkId ? { ...p, paid: Math.max(0, p.paid - payment.amount) } : p);
    if (payment.kind === "Customer receipt") next.orders = next.orders.map(o => o.id === payment.linkId ? { ...o, paid: Math.max(0, o.paid - payment.amount), status: o.status === "Paid" ? "Invoiced" : o.status } : o);
    if (payment.kind === "Supplier refund") next.returns = next.returns.map(r => r.id === payment.linkId ? { ...r, refunded: Math.max(0, r.refunded - payment.amount) } : r);
    setStore(log(next, "Deleted payment", payment.id, `${payment.party} · ${money(payment.amount)}`));
  }

  function deleteExpense(expense:Expense){if(!window.confirm(`Delete ${expense.category.toLowerCase()} expense of ${money(expense.amount)}?`))return;setStore(current=>log({...current,expenses:current.expenses.filter(item=>item.id!==expense.id)},"Deleted expense",expense.id,`${expense.category} · ${money(expense.amount)}`));}

  function setProcessStatus(batch:Batch,process:ProcessEntry,status:ProcessEntry["status"]){if(process.status===status)return;if(status==="In process"&&batch.remaining<process.quantity){notify("Not enough on-hand units are available to reopen this process.");return;}const delta=status==="Completed"?process.quantity:-process.quantity;setStore(current=>log({...current,batches:current.batches.map(item=>item.id===batch.id?{...item,remaining:item.remaining+delta,processes:(item.processes??[]).map(p=>p.id===process.id?{...p,status}:p)}:item)},status==="Completed"?"Completed stock process":"Reopened stock process",batch.vendorName+" / "+batch.product,process.quantity+" units · "+process.process));}
  function completeProcess(batch:Batch,process:ProcessEntry){
    setStore(current=>log({...current,batches:current.batches.map(item=>item.id===batch.id?{...item,processes:(item.processes??[]).map(p=>p.id===process.id?{...p,status:"Completed" as const}:p)}:item)},"Completed stock process",`${batch.vendorName} / ${batch.product}`,`${process.quantity} units · ${process.process}`));
  }

  function removeVendor(vendor: Vendor) {
    if (store.purchases.some(p => p.vendorId === vendor.id) || store.returns.some(r => r.vendorId === vendor.id)) { notify("This supplier has purchase history. Keep the supplier so old invoices and returns remain traceable."); return; }
    if (!window.confirm(`Delete supplier ${vendor.name}?`)) return;
    setStore(current => log({ ...current, vendors: current.vendors.filter(v => v.id !== vendor.id) }, "Deleted supplier", vendor.name, "Supplier had no purchases"));
  }

  function exportCsv() {
    let rows: string[][] = [["Date", "Record", "Name", "Status", "Amount", "Reference"]];
    if (section === "Purchases") rows.push(...purchases.map(p => [p.date, "Purchase", p.vendorName, purchaseDue(store,p) ? "Balance due" : "Settled", String(purchaseTotal(p)+purchaseExtraTotal(p)), p.reference || p.id]));
    else if (section === "Sales" || section === "Reports" || section === "Invoices") rows.push(...orders.filter(o=>o.status!=="Draft").map(o=>[o.created,"Sale",o.customer,o.status,String(saleTotal(o)),o.invoice||o.id]));
    else if(section==="Today's expenses") rows.push(...expenseRows.map(row=>[row.date,row.category,row.payee,row.source,String(row.amount),row.reference]));
    else if(section==="Cash flow"){rows.push(...cashRows.map(p=>[p.date,p.kind,p.party,"Recorded",String(p.amount),p.reference]));rows.push(...expenseRows.filter(row=>row.source!=="Inventory purchase").map(row=>[row.date,row.category,row.payee,row.source,String(row.amount),row.reference]));}
    else rows.push(...cashRows.map(p=>[p.date,p.kind,p.party,"Recorded",String(p.amount),p.reference]));
    const csv=rows.map(row=>row.map(value=>`"${value.replaceAll('"','""')}"`).join(",")).join("\n");
    const link=document.createElement("a");link.href=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));link.download=`d2-garments-${slug(section)}.csv`;link.click();URL.revokeObjectURL(link.href);notify(`${section} list exported to CSV.`);
  }

  function resetAll() {
    if (!window.confirm("Clear all suppliers, products, purchases, inventory, sales, returns, expenses, cash records and activity logs from this browser?")) return;
    localStorage.removeItem(STORE_KEY);localStorage.removeItem(PREVIOUS_KEY);setStore(EMPTY);setModal(null);setSection("Overview");notify("Workspace cleared. All operational records are empty.");
  }

  function actionButton(label: string, click: () => void, icon?: typeof Pencil, danger = false) { const Icon = icon; return <button className={`row-action ${danger?"row-danger":""}`} onClick={click}>{Icon&&<Icon size={15}/>}<span>{label}</span></button>; }
  function addAction() {
    if (section === "Vendors") showModal("vendor");
    else if (section === "Purchases") startPurchase();
    else if (section === "Sales") { if (available <= 0) { open("Purchases"); notify("Record a purchase to receive stock before creating a sales order."); } else showModal("order"); }
    else if(section==="Today's expenses")showModal("expense");
    else if(section==="Invoices")generateSelectedInvoices();
    else if (section === "Cash flow") { if (totalDue > 0) showModal("supplier-payment"); else if (totalReceivable > 0) showModal("customer-payment"); else notify("There are no balances to pay or collect yet."); }
    else if (section === "Profile") open("Profile"); else startPurchase();
  }
  const actionLabel = section === "Vendors" ? "Add supplier" : section === "Purchases" || section === "Inventory" ? "New purchase" : section === "Sales" ? "New sales order" : section === "Today's expenses" ? "Add expense" : section === "Cash flow" ? "Record payment" : section === "Profile" ? "Edit profile" : "New purchase";

  return <div className="app-shell">
    <aside className={`sidebar ${mobileNav ? "sidebar-open" : ""}`}>
      <div className="sidebar-top"><div className="brand"><div className="brand-mark"><span/><span/><span/><span/></div><div className="brand-name">d2<span>garments</span><small>OPERATIONS</small></div></div><button className="icon-button mobile-close" aria-label="Close menu" onClick={()=>setMobileNav(false)}><X size={20}/></button></div>
      <div className="workspace"><div className="workspace-avatar">D2</div><div className="workspace-label"><strong>{store.profile.name}</strong><span>Workspace</span></div><span className="demo-badge">DEMO</span></div>
      <div className="nav-label">WORKSPACE</div><nav className="nav-list">{sections.map(({name,icon:Icon})=><button key={name} className={`nav-item ${section===name?"active":""}`} onClick={()=>open(name)}><Icon size={19}/><span>{name}</span>{name==="Inventory"&&<span className="nav-count">{store.batches.length}</span>}{name==="Sales"&&store.orders.some(o=>o.status==="Draft")&&<span className="nav-count attention">{store.orders.filter(o=>o.status==="Draft").length}</span>}</button>)}</nav>
      <div className="sidebar-bottom"><button className="nav-item settings" onClick={()=>showModal("reset")}><Trash2 size={18}/><span>Reset workspace</span></button><div className="user-card"><div className="user-avatar">{store.profile.name.slice(0,1)||"D"}</div><div className="user-name"><strong>{store.profile.name}</strong><span>Admin workspace</span></div></div></div>
    </aside>
    {mobileNav&&<button className="nav-scrim" onClick={()=>setMobileNav(false)} aria-label="Close menu"/>}
    <main className="main-area">
      <header className="topbar"><div className="topbar-left"><button className="icon-button menu-button" aria-label="Open menu" onClick={()=>setMobileNav(true)}><Menu size={21}/></button><div className="breadcrumb"><span>Workspace</span><ChevronRight size={16}/><strong>{section}</strong></div></div><div className="topbar-actions"><span className="header-avatar">{store.profile.name.slice(0,1)||"D"}</span></div></header>
      <div className="page-content">
        <div className="page-heading"><div><div className="eyebrow"><span className="live-dot"/>{new Date().toLocaleDateString("en-IN",{weekday:"long",day:"numeric",month:"long",year:"numeric"}).toUpperCase()}</div><h1>{detailView?detailTitle(store,detailView):title}</h1><p>{detailView?"Complete account history and payment details.":description[section]}</p></div><div className="heading-actions">{detailView?<button className="button secondary" onClick={()=>setDetailView(null)}>Back to {section}</button>:<><button className="button secondary" onClick={exportCsv}><Download size={17}/>Export</button>{section!=="Invoices"&&<button className="button primary" onClick={addAction} disabled={section==="Reports"||section==="Activity log"}><Plus size={18}/>{actionLabel}</button>}</>}</div></div>
        {!detailView&&section==="Purchases"&&<div className="record-switcher"><button className={purchaseView==="Purchases"?"selected":""} onClick={()=>setPurchaseView("Purchases")}>Purchases <span>{purchases.length}</span></button><button className={purchaseView==="Returns"?"selected":""} onClick={()=>setPurchaseView("Returns")}>Returns <span>{store.returns.filter(r=>inRange(r.date)&&queryMatches(r.id+" "+r.vendorName+" "+r.product+" "+r.reason)).length}</span></button></div>}
        {!detailView&&<div className="global-filters"><label className="filter-search"><Search size={18}/><input aria-label="Search records" placeholder={`Search ${section.toLowerCase()} by name, reference, product…`} value={search} onChange={e=>setSearch(e.target.value)}/>{search&&<button onClick={()=>setSearch("")} aria-label="Clear search"><X size={16}/></button>}</label><label className="date-filter"><span>From</span><input aria-label="Start date" type="date" value={from} max={to||undefined} onChange={e=>setFrom(e.target.value)}/></label><label className="date-filter"><span>To</span><input aria-label="End date" type="date" value={to} min={from||undefined} onChange={e=>setTo(e.target.value)}/></label><button className="clear-filters" onClick={()=>{setSearch("");setFrom("");setTo("")}}>Clear filters</button></div>}
        {message&&<div className="notice" role="status"><span><Check size={18}/>{message}</span><button onClick={()=>setMessage("")} aria-label="Dismiss notification"><X size={17}/></button></div>}
        {!ready?<div className="loading-state">Loading your workspace…</div>:<>{detailView&&<RecordDetailPage store={store} detail={detailView} onOpen={(kind,id)=>id?openDetail(kind,id,section):setDetailView(null)} onPayment={id=>showModal("supplier-payment",id)} onInvoice={id=>{setEditId(id);setModal("invoice")}}/>}
          {!detailView&&section==="Overview"&&<>
            <div className="stat-grid dashboard-totals"><article className="stat-card"><span className="stat-period">Total purchases</span><div className="stat-value">{money(purchaseAmount)}</div><div className="stat-foot">Product purchases in the selected dates</div></article><article className="stat-card"><span className="stat-period">Total sales</span><div className="stat-value">{money(saleValue)}</div><div className="stat-foot">Confirmed orders and invoices</div></article><article className="stat-card"><span className="stat-period">Total expenses</span><div className="stat-value">{money(totalExpenseAmount)}</div><div className="stat-foot">Purchase extras and operating expenses</div></article><article className="stat-card"><span className="stat-period">Total profit</span><div className="stat-value">{money(periodProfit)}</div><div className="stat-foot">Sales before tax less FIFO cost and expenses</div></article></div>
            <section className="panel profit-panel"><div className="panel-heading"><div><h2>Date-wise profit / loss</h2><p>Profit from confirmed sales, less expenses recorded for each date.</p></div><span className="soft-badge">{dailyProfitPoints.length} dates</span></div><ProfitChart points={dailyProfitPoints}/></section>
            <section className="panel aging-panel"><div className="panel-heading"><div><h2>Stock age reminders</h2><p>Unsold stock that has been sitting in inventory.</p></div><button className="text-action" onClick={()=>open("Inventory")}>Review inventory <ArrowRight size={16}/></button></div>{ageReminders.length===0?<p className="chart-empty">No stock has been in inventory for 30 days yet.</p>:<div className="aging-list">{ageReminders.map(batch=><div className="aging-row" key={batch.id}><span className="aging-age">{batch.age>=180?"6+ months":batch.age>=90?"3+ months":"30+ days"}</span><button className="table-action" onClick={()=>openDetail("product",batch.productId,"Inventory")}>{batch.product}</button><span>{batch.vendorName}</span><span>{batch.remaining} units · {batch.age} days old</span></div>)}</div>}</section>
            <div className="content-grid"><section className="panel overview-panel"><div className="panel-heading"><div><h2>Inventory and order status</h2><p>Live totals from the records you enter.</p></div><button className="text-action" onClick={()=>open("Inventory")}>Inventory details <ArrowRight size={16}/></button></div>{store.batches.length===0?<EmptyState icon={Boxes} title="Inventory is empty" text="Record a purchase to receive your first stock lots." action="Add first purchase" onAction={startPurchase}/>:<div className="overview-inventory"><div className="mini-total"><span>Stock on hand</span><strong>{available.toLocaleString("en-IN")} units</strong></div><div className="mini-total"><span>Inventory value at cost</span><strong>{money(inventoryValue)}</strong></div><div className="mini-total"><span>Orders waiting for confirmation</span><strong>{store.orders.filter(o=>o.status==="Draft").length}</strong></div><button className="button secondary" onClick={()=>{open("Sales");showModal("order")}}><Plus size={16}/>Create order from stock</button></div>}</section><section className="panel cash-panel"><div className="panel-heading"><div><h2>Cash position</h2><p>Recorded payments in this date range</p></div><button className="text-action" onClick={()=>open("Cash flow")}>Open ledger <ArrowRight size={16}/></button></div><div className="cash-balance"><div className="cash-icon"><Wallet size={21}/></div><div><span>Net cash movement</span><strong>{money(cashIn-cashOut)}</strong></div></div><div className="cash-flow-row"><div><span><i className="flow-dot in-dot"/>Money received</span><strong>{money(cashIn)}</strong></div><div><span><i className="flow-dot out-dot"/>Money paid</span><strong>{money(cashOut)}</strong></div></div><div className="cash-divider"/><button className="payable-row clickable-row" onClick={()=>open("Purchases")}><span className="payable-copy"><strong>Supplier balance</strong><span>{store.purchases.length} purchase records</span></span><span className="payable-amount">{money(totalDue)}<ArrowRight size={16}/></span></button></section></div>
          </>}
          {!detailView&&section==="Inventory"&&<section className="panel data-panel"><div className="panel-heading"><div><h2>Inventory lots</h2><p>Each lot is tied to its supplier and purchase invoice. Stock sent to a process is reserved from sales until completed.</p></div><div className="heading-actions"><button className="button secondary" onClick={()=>setLowOnly(v=>!v)}>{lowOnly?"Show all lots":"Low stock filter"}</button><button className="button primary" onClick={startPurchase}><Plus size={16}/>New purchase</button></div></div><Table><thead><tr><th>PRODUCT / LOT</th><th>SUPPLIER</th><th>RECEIVED</th><th>IN</th><th>ON HAND</th><th>STATUS</th><th>INVOICE STATUS</th><th>UNIT COST</th><th>ACTIONS</th></tr></thead><tbody>{batches.map(batch=><tr key={batch.id}><td><button className="table-action" onClick={()=>openDetail("product",batch.productId,"Inventory")}>{batch.product}</button><span className="cell-sub">{batch.sku||batch.id} · {batch.category} · {batch.vendorName}</span></td><td>{batch.vendorName}</td><td>{dateText(batch.received)}</td><td>{batch.quantity}</td><td><strong>{batch.remaining}</strong></td><td><select className="process-status-select" aria-label={"Assign process status for "+batch.product} value="" onChange={event=>{if(event.target.value){setProcessType(event.target.value);setEditId(batch.id);setModal("process")}}}><option value="">Assign status…</option><option>Packing</option><option>Stitching</option><option>Finishing</option><option>Quality check</option><option>Embroidery</option><option>Other</option></select>{(batch.processes??[]).length>0?<span className="process-summary">{(batch.processes??[]).map(p=><span className="process-status-row" key={p.id}><small>{p.quantity} sent to {p.process}</small><select aria-label={p.process+" status"} value={p.status} onChange={event=>setProcessStatus(batch,p,event.target.value as ProcessEntry["status"])}><option>In process</option><option>Completed</option></select></span>)}</span>:"Not started"}</td><td><span className={"status-pill "+(purchaseInvoiceStatus(store,batch)==="Paid"?"paid":purchaseInvoiceStatus(store,batch)==="Part paid"?"confirmed":"due")}>{purchaseInvoiceStatus(store,batch)}</span><span className="cell-sub">{store.purchases.find(p=>p.id===batch.purchaseId)?.reference||batch.purchaseId}</span></td><td>{money(batch.materialCost+batch.manufacturingCost)}</td><td><div className="row-actions">{actionButton("Edit purchase",()=>{open("Purchases");showModal("purchase",batch.purchaseId)},Pencil)}</div></td></tr>)}</tbody></Table>{batches.length===0&&<EmptyState icon={Boxes} title="No stock lots found" text="Record a purchase or adjust the search and date range." action="Record purchase" onAction={startPurchase}/>}</section>}
          {!detailView&&section==="Vendors"&&<section className="panel data-panel"><div className="panel-heading"><div><h2>Vendors</h2><p>Supplier contact details. Open a vendor name to see their account history.</p></div><button className="button primary" onClick={()=>showModal("vendor")}><Plus size={17}/>New vendor</button></div>{vendors.length===0?<EmptyState icon={Package} title="No vendors yet" text="Add a vendor to save their name, email address, and business address." action="New vendor" onAction={()=>showModal("vendor")}/>:<div className="vendor-grid">{vendors.map(vendor=><article className="vendor-card" key={vendor.id}><div className="vendor-card-head"><span className="vendor-avatar">{vendor.name.slice(0,1).toUpperCase()}</span><div><button className="table-action" onClick={()=>openDetail("supplier",vendor.id,"Vendors")}>{vendor.name}</button></div><div className="row-actions">{actionButton("Edit",()=>showModal("vendor",vendor.id),Pencil)}{actionButton("Delete",()=>removeVendor(vendor),Trash2,true)}</div></div><div className="vendor-meta vendor-contact-only"><span><small>Email</small>{vendor.email||"Not added"}</span><span><small>Address</small>{vendor.address||"Not added"}</span></div></article>)}</div>}</section>}
          {!detailView&&section==="Purchases"&&<section className="panel data-panel"><div className="panel-heading"><div><h2>{purchaseView==="Purchases"?"Purchases & supplier balances":"Purchase returns"}</h2><p>{purchaseView==="Purchases"?"Record product costs, supplier payments, and extra worker or food costs.":"Review returns linked to their original supplier and purchase."}</p></div><div className="heading-actions"><button className="button secondary" onClick={()=>{setContinueToPurchase(true);setSection("Vendors");showModal("vendor")}}><Plus size={16}/>Add supplier</button><button className="button primary" onClick={startPurchase}><Plus size={16}/>New purchase</button></div></div>{purchaseView==="Purchases"&&<div className="ledger-summary purchase-summary"><div><span>Stock purchase total</span><strong>{money(purchases.reduce((sum,p)=>sum+purchaseTotal(p),0))}</strong></div><div><span>Extra purchase expenses</span><strong>{money(purchases.reduce((sum,p)=>sum+purchaseExtraTotal(p),0))}</strong></div><div><span>Paid to suppliers</span><strong>{money(purchases.reduce((sum,p)=>sum+p.paid,0))}</strong></div><div><span>Realized profit / loss</span><strong>{money(purchases.reduce((sum,p)=>sum+realizedPurchaseProfit(store,p),0))}</strong></div></div>}
          {purchaseView==="Purchases"&&<><Table><thead><tr><th>PURCHASE / SUPPLIER</th><th>PRODUCTS</th><th>DATE</th><th>STOCK VALUE</th><th>OTHER COSTS</th><th>PAID TO SUPPLIER</th><th>SUPPLIER DUE</th><th>REALIZED PROFIT / LOSS</th><th>ACTIONS</th></tr></thead><tbody>{purchases.map(purchase=><tr key={purchase.id}><td><button className="table-action" onClick={()=>openDetail("supplier",purchase.vendorId,"Purchases")}>{purchase.vendorName}</button><button className="cell-sub table-action" onClick={()=>openDetail("purchase",purchase.id,"Purchases")}>{purchase.id}{purchase.reference?" · "+purchase.reference:""}</button></td><td>{purchase.items.map(item=><button className="tag-line table-action" key={item.id} onClick={()=>openDetail("product",item.productId,"Inventory")}>{item.name} × {item.quantity}</button>)}{(purchase.extraExpenses??[]).map(item=><span className="tag-line cost-line" key={item.id}>{item.description}: {money(item.amount)}</span>)}</td><td>{dateText(purchase.date)}</td><td>{money(purchaseTotal(purchase))}</td><td>{money(purchaseExtraTotal(purchase))}</td><td>{money(purchase.paid)}</td><td>{money(purchaseDue(store,purchase))}</td><td className={realizedPurchaseProfit(store,purchase)>=0?"positive-amount":"negative-amount"}>{money(realizedPurchaseProfit(store,purchase))}</td><td><div className="row-actions">{actionButton("Edit",()=>showModal("purchase",purchase.id),Pencil)}{actionButton("Return",()=>showModal("purchase-return",purchase.id),ArrowDownLeft)}{actionButton("Delete",()=>deletePurchase(purchase),Trash2,true)}{purchaseDue(store,purchase)>0&&actionButton("Pay",()=>showModal("supplier-payment",purchase.id),Wallet)}</div></td></tr>)}</tbody></Table>{purchases.length===0&&<EmptyState icon={ClipboardList} title="No purchases found" text="Use search or date filters, or add your first supplier purchase." action="Record purchase" onAction={startPurchase}/>}</>}
          {purchaseView==="Returns"&&<><div className="subsection-heading"><h3>Returns</h3><span>Supplier, product lot, and settlement remain connected</span></div><Table><thead><tr><th>RETURN</th><th>SUPPLIER</th><th>PRODUCT</th><th>DATE</th><th>QUANTITY</th><th>VALUE</th><th>SETTLEMENT</th><th>ACTIONS</th></tr></thead><tbody>{store.returns.filter(r=>inRange(r.date)&&queryMatches(r.id+" "+r.vendorName+" "+r.product+" "+r.reason)).map(r=><tr key={r.id}><td><button className="table-action" onClick={()=>openDetail("purchase",r.purchaseId,"Purchases")}>{r.id}</button><span className="cell-sub">{r.purchaseId}</span></td><td><button className="table-action" onClick={()=>openDetail("supplier",r.vendorId,"Purchases")}>{r.vendorName}</button></td><td><button className="table-action" onClick={()=>openDetail("product",r.productId,"Inventory")}>{r.product}</button></td><td>{dateText(r.date)}</td><td>{r.quantity}</td><td>{money(r.amount)}</td><td><span className={"status-pill "+(r.refunded>=r.amount?"paid":"due")}>{r.disposition}{r.disposition==="Refund due"?" · "+money(r.amount-r.refunded)+" open":""}</span></td><td><div className="row-actions">{actionButton("Edit",()=>{setEditId(r.purchaseId);setEditReturnId(r.id);setModal("purchase-return")},Pencil)}{actionButton("Delete",()=>deleteReturn(r),Trash2,true)}{r.disposition==="Refund due"&&r.refunded<r.amount?actionButton("Record refund",()=>showModal("supplier-refund",r.id),Wallet):null}</div></td></tr>)}</tbody></Table>{store.returns.filter(r=>inRange(r.date)&&queryMatches(r.id+" "+r.vendorName+" "+r.product+" "+r.reason)).length===0&&<EmptyState icon={ArrowDownLeft} title="No returns found" text="Use search or date filters to find a supplier return."/>}</>}
          </section>}
          {!detailView&&section==="Sales"&&<section className="panel data-panel"><div className="panel-heading"><div><h2>Sales &amp; invoices</h2><p>Draft → Confirm order (deduct FIFO lots) → Generate invoice → Record payment.</p></div><button className="button primary" onClick={()=>showModal("order")} disabled={available===0}><Plus size={17}/>New sales order</button></div><div className="order-flow-note"><span>Draft order</span><ChevronRight size={16}/><span>Confirm &amp; deduct stock</span><ChevronRight size={16}/><span>Generate invoice</span><ChevronRight size={16}/><span>Record payment</span></div><Table><thead><tr><th>ORDER / CUSTOMER</th><th>PRODUCTS</th><th>TYPE</th><th>DATE</th><th>ORDER TOTAL</th><th>PAID / DUE</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>{orders.map(order=><tr key={order.id}><td><button className="table-action" onClick={()=>openDetail("customer",order.customer,"Sales")}>{order.customer}</button><span className="cell-sub">{order.invoice||order.id}</span></td><td>{order.items.map(item=><button className="tag-line table-action" key={item.id} onClick={()=>openDetail("product",item.productId,"Inventory")}>{item.product} × {item.quantity}</button>)}</td><td>{order.channel}</td><td>{dateText(order.created)}</td><td>{money(saleTotal(order))}</td><td>{money(order.paid)} / {money(Math.max(0,saleTotal(order)-order.paid))}</td><td><span className={`status-pill ${order.status.toLowerCase()}`}>{order.status}</span></td><td><div className="row-actions">{order.status==="Draft"?actionButton("Confirm",()=>confirmOrder(order),Check):order.status==="Confirmed"?actionButton("Invoice",()=>createInvoice(order),FileText):<>{actionButton("Invoice",()=>{setEditId(order.id);setModal("invoice")},FileText)}{order.status!=="Paid"&&actionButton("Receive",()=>showModal("customer-payment",order.id),Wallet)}</>}{actionButton("Edit",()=>showModal("order",order.id),Pencil)}{actionButton("Delete",()=>deleteOrder(order),Trash2,true)}</div></td></tr>)}</tbody></Table>{orders.length===0&&<EmptyState icon={ShoppingBag} title="No sales orders found" text={available>0?"Create an order using stock already in inventory.":"Record a purchase first. Items received into stock will be available in the sales order form."} action={available>0?"Create order":undefined} onAction={()=>showModal("order")}/>}</section>}
          {!detailView&&section==="Invoices"&&<section className="panel data-panel"><div className="panel-heading"><div><h2>Sales invoices</h2><p>Select the checkbox to include all visible orders, then download their invoices in one PDF.</p></div><button className="button primary" onClick={generateSelectedInvoices} disabled={selectedInvoices.length===0}><Download size={17}/>Generate &amp; download ({selectedInvoices.length})</button></div><Table><thead><tr><th><input type="checkbox" aria-label="Select all sales orders" checked={invoiceOrders.length>0&&invoiceOrders.every(order=>selectedInvoices.includes(order.id))} onChange={event=>setSelectedInvoices(event.target.checked?invoiceOrders.map(order=>order.id):[])}/></th><th>ORDER / CUSTOMER</th><th>PRODUCTS</th><th>DATE</th><th>TOTAL</th><th>PAID / DUE</th><th>INVOICE STATUS</th><th>ACTIONS</th></tr></thead><tbody>{invoiceOrders.map(order=><tr key={order.id}><td><input type="checkbox" aria-label={"Select "+order.id} checked={selectedInvoices.includes(order.id)} onChange={event=>toggleInvoice(order.id,event.target.checked)}/></td><td><button className="table-action" onClick={()=>openDetail("customer",order.customer,"Invoices")}>{order.customer}</button><button className="cell-sub table-action" onClick={()=>{setEditId(order.id);setModal("invoice")}}>{order.invoice||order.id}</button></td><td>{order.items.map(item=><button className="tag-line table-action" key={item.id} onClick={()=>openDetail("product",item.productId,"Inventory")}>{item.product} × {item.quantity}</button>)}</td><td>{dateText(order.created)}</td><td>{money(saleTotal(order))}</td><td>{money(order.paid)} / {money(Math.max(0,saleTotal(order)-order.paid))}</td><td><span className={"status-pill "+(order.invoice?"invoiced":"confirmed")}>{order.invoice?"Invoice generated":"Ready to invoice"}</span><span className="cell-sub">{order.invoice||"—"}</span></td><td><div className="row-actions">{actionButton("Order details",()=>openDetail("customer",order.customer,"Sales"),Eye)}</div></td></tr>)}</tbody></Table>{invoiceOrders.length===0&&<EmptyState icon={FileText} title="No confirmed sales to invoice" text="Confirm an order in Sales, then it will be available here." action="Go to Sales" onAction={()=>setSection("Sales")}/>}</section>}
          {!detailView&&section==="Today's expenses"&&<section className="panel data-panel"><div className="panel-heading"><div><h2>Today's expenses</h2><p>Purchases, staff and operating costs recorded by date. Use the filters above to review another period.</p></div><button className="button primary" onClick={()=>showModal("expense")}><Plus size={17}/>Add expense</button></div><div className="ledger-summary"><div><span>Today's recorded cost</span><strong>{money(todayExpenseTotal)}</strong></div><div><span>Supplier purchases today</span><strong>{money(store.purchases.filter(p=>p.date===isoDate()).reduce((sum,p)=>sum+purchaseTotal(p),0))}</strong></div><div><span>Other / staff expenses today</span><strong>{money(store.expenses.filter(e=>e.date===isoDate()).reduce((sum,e)=>sum+e.amount,0)+store.purchases.filter(p=>p.date===isoDate()).reduce((sum,p)=>sum+purchaseExtraTotal(p),0))}</strong></div><div><span>Entries in selected dates</span><strong>{expenseRows.length}</strong></div></div><Table><thead><tr><th>DATE</th><th>TYPE</th><th>PAID TO / SUPPLIER</th><th>DESCRIPTION</th><th>AMOUNT</th><th>REFERENCE</th><th>ACTIONS</th></tr></thead><tbody>{expenseRows.map(row=><tr key={row.id}><td>{dateText(row.date)}</td><td>{row.category}</td><td><button className="table-action" onClick={()=>row.source==="Expense"?openDetail("expense",row.id,"Today's expenses"):openDetail("purchase",row.source==="Purchase expense"?row.reference:store.purchases.find(p=>p.id===row.reference)?.id??row.reference,"Today's expenses")}>{row.payee}</button></td><td>{row.description}</td><td>{money(row.amount)}</td><td>{row.reference||"—"}</td><td><div className="row-actions">{row.source==="Expense"?<>{actionButton("Edit",()=>showModal("edit-expense",row.id),Pencil)}{actionButton("Delete",()=>deleteExpense(store.expenses.find(e=>e.id===row.id)!),Trash2,true)}</>:row.source==="Purchase expense"?actionButton("Edit purchase",()=>showModal("purchase",store.purchases.find(p=>p.id===row.reference)?.id??""),Pencil):null}</div></td></tr>)}</tbody></Table>{expenseRows.length===0&&<EmptyState icon={CircleDollarSign} title="No expense entries found" text="Purchase, record staff or food expenses, or change the date and search filters." action="Record expense" onAction={()=>showModal("expense")}/>}</section>}
          {!detailView&&section==="Cash flow"&&<>
            <div className="cashflow-hero"><div><span className="eyebrow">OWNER CASH POSITION</span><h2>{money(cashIn-cashOut)}</h2><p>Total receipts less supplier payments and recorded operating costs.</p></div><div className="heading-actions"><button className="button secondary" onClick={()=>showModal("supplier-payment")} disabled={store.purchases.every(p=>purchaseDue(store,p)===0)}>Pay supplier</button><button className="button secondary" onClick={()=>showModal("expense")}><Plus size={16}/>Record spending</button><button className="button primary" onClick={()=>showModal("customer-payment")} disabled={store.orders.every(o=>o.status!=="Invoiced"||saleTotal(o)<=o.paid)}><Plus size={16}/>Receive customer money</button></div></div>
            <section className="panel data-panel cash-ledger-panel">
              <div className="cash-ledger-filters"><label>Show activity<select value={cashFlowFilter} onChange={event=>setCashFlowFilter(event.target.value as CashFlowFilter)}><option>All activity</option><option>Customer receipts</option><option>Purchases</option><option>Supplier payments</option><option>Other expenses</option></select></label><label>Filter by customer receipt<select value={cashSourceFilter} onChange={event=>setCashSourceFilter(event.target.value)}><option value="">All funding sources</option>{store.payments.filter(p=>p.kind==="Customer receipt").map(p=><option key={p.id} value={p.id}>{p.party} · {p.reference||p.id} · {money(p.amount)} received</option>)}</select></label><div className="cash-filter-note">Choose a customer receipt to see what was purchased or paid using that money.</div></div>
              {selectedCashReceipt?<div className="ledger-summary cash-summary"><div><span>Receipt from {selectedCashReceipt.party}</span><strong>{money(selectedCashReceipt.amount)}</strong></div><div><span>Purchase budget assigned</span><strong>{money(selectedReceiptBudget)}</strong></div><div><span>Paid / spent so far</span><strong>{money(selectedActualSpent)}</strong></div><div><span>Receipt amount unassigned</span><strong>{money(Math.max(0,selectedCashReceipt.amount-receiptAllocated(store,selectedCashReceipt.id)))}</strong></div></div>:<div className="ledger-summary cash-summary"><div><span>Money received</span><strong className="positive-amount">{money(cashIn)}</strong></div><div><span>Paid to suppliers</span><strong>{money(store.payments.filter(p=>p.kind==="Supplier payment"&&inRange(p.date)).reduce((sum,p)=>sum+p.amount,0))}</strong></div><div><span>Other expenses recorded</span><strong>{money(operatingExpenses+purchaseAdditionalExpenses)}</strong></div><div><span>Open supplier / customer balances</span><strong>{money(totalDue+totalReceivable)}</strong></div></div>}
              {selectedCashReceipt&&selectedReceiptExpenses.length>0&&<p className="cash-source-extra">Other direct expenses assigned: {money(selectedReceiptExpenses.reduce((sum,e)=>sum+e.amount,0))}</p>}
              <div className="panel-heading"><div><h2>{cashFlowFilter==="All activity"?"Receipts and spending":cashFlowFilter}</h2><p>Every row separates the funding source, who received the money, amount, and purchase balance.</p></div><span className="soft-badge">{cashFlowRows.length} records</span></div>
              <Table><thead><tr><th>DATE</th><th>ACTIVITY / REFERENCE</th><th>FUNDED FROM</th><th>PAID TO / RECEIVED FROM</th><th>AMOUNT / PURCHASE BUDGET</th><th>PAID / BALANCE</th></tr></thead><tbody>{cashFlowRows.map(row=><tr key={row.kind+row.id}><td>{dateText(row.date)}</td><td><span className={"status-pill "+(row.kind==="Customer receipts"?"paid":row.kind==="Purchases"?"confirmed":"due")}>{row.kind}</span><span className="cell-sub">{row.reference}</span></td><td>{row.kind==="Customer receipts"?"Customer receipt":row.sourcePaymentId?<button className="table-action" onClick={()=>setCashSourceFilter(row.sourcePaymentId!)}>{row.sourceName}</button>:"General cash / bank"}</td><td><button className="table-action" onClick={()=>openDetail(row.detailKind,row.id,"Cash flow")}>{row.party}</button></td><td className={row.kind==="Customer receipts"||row.kind==="Supplier refunds"?"positive-amount":row.kind==="Purchases"?"":"negative-amount"}>{row.kind==="Customer receipts"||row.kind==="Supplier refunds"?"+":row.kind==="Purchases"?"Budget ":"-"}{money(row.amount)}</td><td>{row.status}</td></tr>)}</tbody></Table>
              {cashFlowRows.length===0&&<EmptyState icon={Wallet} title="No matching cash-flow records" text="Choose another filter or record a customer receipt, supplier payment, or expense."/>}
            </section>
          </>}
          {!detailView&&section==="Reports"&&<section className="panel data-panel"><div className="panel-heading"><div><h2>Purchases, sales &amp; profitability</h2><p>Dates and search filters above apply to each report table and totals.</p></div><button className="button secondary" onClick={exportCsv}><Download size={17}/>Download filtered CSV</button></div><div className="ledger-summary report-summary"><div><span>Purchase value</span><strong>{money(purchases.reduce((sum,p)=>sum+purchaseTotal(p),0))}</strong></div><div><span>Invoiced total including tax</span><strong>{money(orders.filter(o=>o.status!=="Draft").reduce((sum,o)=>sum+saleTotal(o),0))}</strong></div><div><span>FIFO cost + manufacturing</span><strong>{money(orders.filter(o=>o.status!=="Draft").reduce((sum,o)=>sum+saleCost(o),0))}</strong></div><div><span>Gross profit before tax</span><strong>{money(orders.filter(o=>o.status!=="Draft").reduce((sum,o)=>sum+saleSubtotal(o)-saleCost(o),0))}</strong></div></div><h3>Sales margin by order</h3><Table><thead><tr><th>DATE</th><th>INVOICE / ORDER</th><th>CUSTOMER</th><th>PRODUCTS</th><th>SALES</th><th>FIFO COST</th><th>GROSS PROFIT</th></tr></thead><tbody>{orders.filter(o=>o.status!=="Draft").map(order=><tr key={order.id}><td>{dateText(order.created)}</td><td>{order.invoice||order.id}</td><td>{order.customer}</td><td>{order.items.map(item=>`${item.product} × ${item.quantity}`).join(", ")}</td><td>{money(saleTotal(order))}</td><td>{money(saleCost(order))}</td><td className={saleSubtotal(order)>=saleCost(order)?"positive-amount":"negative-amount"}>{money(saleSubtotal(order)-saleCost(order))}</td></tr>)}</tbody></Table>{orders.filter(o=>o.status!=="Draft").length===0&&<EmptyState icon={FileChartColumn} title="No confirmed orders in this range" text="Confirmed orders will appear with the cost of stock consumed from each vendor lot."/>}<h3>Purchases by supplier</h3><Table><thead><tr><th>DATE</th><th>SUPPLIER</th><th>PRODUCTS</th><th>PURCHASE VALUE</th><th>PAID</th><th>DUE</th></tr></thead><tbody>{purchases.map(p=><tr key={p.id}><td>{dateText(p.date)}</td><td>{p.vendorName}</td><td>{p.items.map(item=>`${item.name} × ${item.quantity}`).join(", ")}</td><td>{money(purchaseTotal(p))}</td><td>{money(p.paid)}</td><td>{money(purchaseDue(store,p))}</td></tr>)}</tbody></Table></section>}
          {!detailView&&section==="Activity log"&&<section className="panel data-panel"><div className="panel-heading"><div><h2>Activity history</h2><p>Every new record, edit, deletion, invoice, payment, and return is timestamped here.</p></div><span className="soft-badge">{logs.length} changes</span></div><Table><thead><tr><th>DATE &amp; TIME</th><th>USER</th><th>ACTION</th><th>RECORD</th><th>DETAILS</th></tr></thead><tbody>{logs.map(item=><tr key={item.id}><td>{new Date(item.dateTime).toLocaleString("en-IN",{dateStyle:"medium",timeStyle:"short"})}</td><td>{item.actor}</td><td><strong>{item.action}</strong></td><td>{item.record}</td><td>{item.detail||"—"}</td></tr>)}</tbody></Table>{logs.length===0&&<EmptyState icon={Activity} title="No activity recorded yet" text="Actions such as creating a supplier, purchase, sale, return or payment will be logged with the exact time."/>}</section>}
          {!detailView&&section==="Profile"&&<section className="panel profile-panel"><div className="panel-heading"><div><h2>Invoice From details</h2><p>These business, contact and bank details appear on generated invoices.</p></div></div><form onSubmit={saveProfile}><div className="profile-grid"><label>Business / company name<input name="name" required defaultValue={store.profile.name}/></label><label>Business email<input name="email" type="email" defaultValue={store.profile.email}/></label><label>Contact number<input name="phone" defaultValue={store.profile.phone}/></label><label>GSTIN<input name="gstin" defaultValue={store.profile.gstin}/></label><label className="wide-field">Business address<textarea name="address" rows={3} defaultValue={store.profile.address}/></label><label>Bank name<input name="bank" defaultValue={store.profile.bank}/></label><label>Account holder name<input name="accountName" defaultValue={store.profile.accountName}/></label><label>Account number<input name="accountNumber" defaultValue={store.profile.accountNumber}/></label><label>IFSC code<input name="ifsc" defaultValue={store.profile.ifsc}/></label></div><div className="profile-actions"><span>Invoice From: <strong>{store.profile.name}</strong> · To: the order customer</span><button className="button primary" type="submit"><Check size={17}/>Save profile</button></div></form></section>}
        </>}
        <footer className="page-footer"><span><Activity size={15}/>{store.profile.name} · Operations workspace</span><span>Search and date filters apply to this section <i>·</i><button onClick={()=>showModal("reset")}>Reset workspace</button></span></footer>
      </div>
    </main>
    {modal&&<div className="modal-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget)setModal(null)}}>
      {modal==="invoice"&&selectedOrder&&<InvoiceModal order={selectedOrder} profile={store.profile} payments={store.payments.filter(p=>p.kind==="Customer receipt"&&p.linkId===selectedOrder.id)} onClose={()=>setModal(null)} onPrint={()=>window.print()} onReceive={()=>showModal("customer-payment",selectedOrder.id)}/>}
      {modal==="reset"&&<div className="modal reset-modal"><div className="modal-head"><span className="modal-symbol"><Settings2 size={20}/></span><button className="icon-button" onClick={()=>setModal(null)} aria-label="Close"><X size={19}/></button></div><h2>Reset workspace?</h2><p>This removes suppliers, vendor products, purchases, stock, orders, returns, expense records, cash transactions and logs from this browser.</p><div className="modal-actions"><button className="button secondary" onClick={()=>setModal(null)}>Cancel</button><button className="button danger" onClick={resetAll}>Clear workspace</button></div></div>}
      {(modal==="expense"||modal==="edit-expense")&&<ModalForm title={modal==="edit-expense"?"Edit expense":"Record owner expense"} description="Log salary, food, fees, or another amount spent. Link it to a customer receipt to track where incoming funds went." onClose={()=>setModal(null)} onSubmit={submit} submitLabel={modal==="edit-expense"?"Save expense":"Record expense"}><ExpenseFields expense={store.expenses.find(item=>item.id===editId)} store={store}/></ModalForm>}
      {modal==="vendor"&&<ModalForm title={store.vendors.find(v=>v.id===editId)?"Edit supplier":"Add supplier"} description="Create this supplier once. Reuse their profile and catalog for every purchase." onClose={()=>setModal(null)} onSubmit={submit} submitLabel="Save supplier"><VendorFields vendor={store.vendors.find(v=>v.id===editId)}/></ModalForm>}
      {modal==="product"&&<ModalForm title={vendorContext?"Edit supplier product":"Add product to supplier catalog"} description={`Product identity is unique within ${store.vendors.find(v=>v.id===editId)?.name??"this supplier"}. The same garment from another supplier stays linked to that other supplier’s lots.`} onClose={()=>setModal(null)} onSubmit={submit} submitLabel="Save product"><ProductFields product={store.vendors.find(v=>v.id===editId)?.products.find(p=>p.id===vendorContext)}/></ModalForm>}
      {modal==="process"&&<ModalForm title="Send stock to process" description="Track quantities sent for packing, stitching, finishing, or another production step." onClose={()=>setModal(null)} onSubmit={submit} submitLabel="Record process"><ProcessFields batch={store.batches.find(b=>b.id===editId)} initialProcess={processType}/></ModalForm>}
      {modal==="purchase"&&<ModalForm title={store.purchases.find(p=>p.id===editId)?"Edit purchase":"New supplier purchase"} description="Choose a saved supplier and add as many product lines as needed. Each line creates its own lot and vendor-linked product." onClose={()=>setModal(null)} onSubmit={submit} submitLabel={editId?"Save purchase":"Confirm purchase & receive stock"} wide><PurchaseFields vendors={store.vendors} store={store} purchase={store.purchases.find(p=>p.id===editId)} count={lineCount} setCount={setLineCount} expenseCount={purchaseExpenseCount} setExpenseCount={setPurchaseExpenseCount} batches={store.batches}/></ModalForm>}
      {modal==="purchase-return"&&<ModalForm title={editReturnId?"Edit purchase return":"Return items to supplier"} description="Select an unallocated quantity from the original purchase. The correct vendor and source lot remain attached to this return." onClose={()=>setModal(null)} onSubmit={submit} submitLabel={editReturnId?"Save return changes":"Record return"}><ReturnFields purchase={store.purchases.find(p=>p.id===editId)} batches={store.batches} returned={store.returns.find(r=>r.id===editReturnId)}/></ModalForm>}
      {modal==="order"&&<ModalForm title={selectedOrder?"Edit sales order":"Create sales order"} description="A draft does not consume stock. Confirm the order to reserve the oldest available stock lots." onClose={()=>setModal(null)} onSubmit={submit} submitLabel="Save draft order" wide><OrderFields vendors={store.vendors} batches={store.batches} count={lineCount} setCount={setLineCount} order={selectedOrder}/></ModalForm>}
      {(modal==="supplier-payment"||modal==="customer-payment"||modal==="supplier-refund"||modal==="edit-payment")&&<ModalForm title={modal==="supplier-payment"?"Pay supplier":modal==="customer-payment"?"Receive customer payment":modal==="supplier-refund"?"Record supplier refund":"Edit cash transaction"} description="The selected amount must stay within the open balance. The related account and cash ledger update together." onClose={()=>setModal(null)} onSubmit={submit} submitLabel={modal==="edit-payment"?"Save payment changes":"Record payment"}><PaymentFields mode={modal} store={store} target={editId||refundReturnId} payment={store.payments.find(p=>p.id===editId)}/></ModalForm>}
    </div>}
    <style jsx global>{`@media print{body *{visibility:hidden!important}.invoice-modal,.invoice-modal *{visibility:visible!important}.invoice-modal{position:fixed!important;inset:0!important;width:100%!important;max-width:100%!important;box-shadow:none!important;border:0!important}.invoice-modal .modal-actions,.invoice-modal .icon-button{display:none!important}}`}</style>
  </div>;
}

function batchesFor(store:Store, productId?:string) { return store.batches.filter(batch=>!productId||batch.productId===productId); }
function processQuantity(batch:Batch) { return (batch.processes??[]).filter(item=>item.status==="In process").reduce((sum,item)=>sum+item.quantity,0); }
function sellableQuantity(batch:Batch) { return Math.max(0,batch.remaining); }
function purchaseInvoiceStatus(store:Store,batch:Batch) { const purchase=store.purchases.find(item=>item.id===batch.purchaseId);if(!purchase)return "Unknown";return purchase.paid>=purchaseTotal(purchase)?"Paid":purchase.paid>0?"Part paid":"Unpaid"; }
function realizedPurchaseProfit(store:Store,purchase:Purchase){let revenue=0,cost=0,unitsSold=0;for(const order of store.orders.filter(item=>item.status!=="Draft")){for(const line of order.items){for(const allocation of line.allocations){const batch=store.batches.find(item=>item.id===allocation.batchId);if(batch?.purchaseId===purchase.id){revenue+=allocation.quantity*line.price;cost+=allocation.quantity*(batch.materialCost+batch.manufacturingCost);unitsSold+=allocation.quantity;}}}}const stockUnits=Math.max(1,purchase.items.reduce((sum,item)=>sum+item.quantity-item.returned,0));return revenue-cost-purchaseExtraTotal(purchase)*Math.min(1,unitsSold/stockUnits);}
function makeDailyProfitPoints(store:Store,from:string,to:string){const totals=new Map<string,number>();const add=(date:string,value:number)=>{const day=date.slice(0,10);if((!from||day>=from)&&(!to||day<=to))totals.set(day,(totals.get(day)??0)+value)};store.orders.filter(order=>order.status!=="Draft").forEach(order=>add(order.created,saleSubtotal(order)-saleCost(order)));store.purchases.forEach(purchase=>add(purchase.date,-purchaseExtraTotal(purchase)));store.expenses.forEach(expense=>add(expense.date,-expense.amount));return [...totals.entries()].sort(([a],[b])=>a.localeCompare(b)).slice(-21).map(([date,profit])=>({date,profit}));}

function ProfitChart({points}:{points:{date:string;profit:number}[]}){if(!points.length)return <div className="chart-empty">Confirmed sales and expenses will appear here by date.</div>;const width=900,height=250,left=58,right=22,top=18,bottom=42;const vals=points.map(p=>p.profit);const min=Math.min(0,...vals),max=Math.max(0,...vals);const pad=Math.max(1,(max-min)*.12);const low=min-pad,high=max+pad;const x=(i:number)=>left+(points.length===1?(width-left-right)/2:i*(width-left-right)/(points.length-1));const y=(v:number)=>top+(high-v)*(height-top-bottom)/(high-low);const line=points.map((p,i)=>`${i===0?"M":"L"} ${x(i)} ${y(p.profit)}`).join(" ");const tickIndexes=[...new Set([0,Math.floor((points.length-1)/4),Math.floor((points.length-1)/2),Math.floor(3*(points.length-1)/4),points.length-1])];return <div className="profit-chart"><svg viewBox={`0 0 ${width} ${height}`} role="img" aria-label="Date-wise profit and loss chart"><line x1={left} x2={width-right} y1={y(0)} y2={y(0)} className="chart-zero"/><line x1={left} x2={left} y1={top} y2={height-bottom} className="chart-axis"/><path d={line} className="profit-line"/>{points.map((p,i)=><circle key={p.date} cx={x(i)} cy={y(p.profit)} r="3.5" className={p.profit<0?"profit-dot loss":"profit-dot"}><title>{dateText(p.date)} · {money(p.profit)}</title></circle>)}{tickIndexes.map(i=><text key={i} x={x(i)} y={height-12} textAnchor="middle" className="chart-date">{new Date(`${points[i].date}T12:00:00`).toLocaleDateString("en-IN",{day:"2-digit",month:"short"})}</text>)}<text x="8" y={Math.max(12,y(high))} className="chart-value">{money(high)}</text><text x="8" y={Math.min(height-28,y(low))} className="chart-value">{money(low)}</text></svg></div>}
function Table({children}:{children:React.ReactNode}) { return <div className="table-wrap"><table>{children}</table></div>; }
function ModalForm({title,description,onClose,onSubmit,submitLabel,wide,children}:{title:string;description:string;onClose:()=>void;onSubmit:(event:FormEvent<HTMLFormElement>)=>void;submitLabel:string;wide?:boolean;children:React.ReactNode}) { return <form className={`modal ${wide?"modal-wide":""}`} onSubmit={onSubmit}><div className="modal-head"><span className="modal-symbol"><ClipboardList size={20}/></span><button type="button" className="icon-button" onClick={onClose} aria-label="Close dialog"><X size={19}/></button></div><h2>{title}</h2><p>{description}</p><div className="modal-body">{children}</div><div className="modal-actions"><button type="button" className="button secondary" onClick={onClose}>Cancel</button><button type="submit" className="button primary"><Check size={17}/>{submitLabel}</button></div></form>; }
function VendorFields({vendor}:{vendor?:Vendor}) { return <><label>Supplier name<input name="name" required defaultValue={vendor?.name} placeholder="Supplier or manufacturer"/></label><div className="form-row"><label>Contact number<input name="phone" defaultValue={vendor?.phone} placeholder="Phone"/></label><label>Email address<input name="email" type="email" defaultValue={vendor?.email} placeholder="Email"/></label></div><label>Address<textarea name="address" rows={2} defaultValue={vendor?.address} placeholder="Business address"/></label><div className="form-row"><label>Bank name<input name="bank" defaultValue={vendor?.bank}/></label><label>Account holder<input name="accountName" defaultValue={vendor?.accountName}/></label></div><div className="form-row"><label>Account number<input name="accountNumber" defaultValue={vendor?.accountNumber}/></label><label>IFSC code<input name="ifsc" defaultValue={vendor?.ifsc}/></label></div></>; }
function ProductFields({product}:{product?:VendorProduct}) { return <><label>Product name<input name="name" required defaultValue={product?.name} placeholder="e.g. Cotton saree"/></label><div className="form-row"><label>Product code / SKU<input name="sku" defaultValue={product?.sku} placeholder="Optional code"/></label><label>Category<select name="category" defaultValue={product?.category??"Sarees"}><option>Sarees</option><option>Salwar suits</option><option>Kurtis</option><option>Blouses</option><option>T-shirts</option><option>Shirts</option><option>Bottoms</option><option>Other</option></select></label></div></>; }
function PurchaseFields({vendors,store,purchase,count,setCount,expenseCount,setExpenseCount,batches}:{vendors:Vendor[];store:Store;purchase?:Purchase;count:number;setCount:(n:number)=>void;expenseCount:number;setExpenseCount:(n:number)=>void;batches:Batch[]}) {
  const items=purchase?.items??[];const extraExpenses=purchase?.extraExpenses??[];const receipts=store.payments.filter(payment=>payment.kind==="Customer receipt");
  const [lineValues,setLineValues]=useState<Record<number,{quantity:number;unitCost:number}>>(()=>Object.fromEntries(items.map((item,index)=>[index,{quantity:item.quantity,unitCost:item.materialCost+item.manufacturingCost}])));
  const [extraValues,setExtraValues]=useState<Record<number,number>>(()=>Object.fromEntries(extraExpenses.map((item,index)=>[index,item.amount])));
  const productSubtotal=Array.from({length:Math.max(1,count)}).reduce<number>((sum,_,index)=>{const saved=items[index];const value=lineValues[index];return sum+(value?.quantity??saved?.quantity??0)*(value?.unitCost??(saved? saved.materialCost+saved.manufacturingCost:0));},0);
  const otherExpenseTotal=Array.from({length:Math.max(1,expenseCount)}).reduce<number>((sum,_,index)=>sum+(extraValues[index]??extraExpenses[index]?.amount??0),0);
  const purchaseGrandTotal=productSubtotal+otherExpenseTotal;
  return <><div className="form-row"><label>Supplier<select name="vendorId" required defaultValue={purchase?.vendorId??""}><option value="">Choose saved supplier</option>{vendors.map(v=><option key={v.id} value={v.id}>{v.name}</option>)}</select></label><label>Purchase date<input name="date" type="date" required defaultValue={purchase?.date??isoDate()}/></label></div>{vendors.length===0&&<div className="inline-hint">Create a supplier profile in the Vendors tab first so the product catalog is linked correctly.</div>}<label>Supplier invoice / reference<input name="reference" defaultValue={purchase?.reference} placeholder="Invoice or delivery reference"/></label><div className="line-editor-head"><strong>Products in this purchase</strong><button type="button" className="table-action" onClick={()=>setCount(count+1)}><Plus size={15}/>Add product line</button></div>{Array.from({length:Math.max(1,count)}).map((_,index)=>{const item=items[index];return <div className="purchase-line-editor" key={item?.id??index}><div className="line-number">{index+1}</div><button type="button" className="line-remove" aria-label="Remove product line" onClick={()=>setCount(Math.max(1,count-1))}><X size={14}/></button><div className="purchase-line-grid"><label>Product name<input name={`product-${index}`} required defaultValue={item?.name} list="vendor-product-list" placeholder="Product"/></label><label>SKU<input name={`sku-${index}`} defaultValue={item?.sku} placeholder="Optional"/></label><label>Quantity<input name={`quantity-${index}`} required type="number" min="1" defaultValue={item?.quantity} placeholder="0" onChange={event=>setLineValues(current=>({...current,[index]:{quantity:Number(event.target.value),unitCost:current[index]?.unitCost??item?.materialCost??0}}))}/></label><label>Cost per unit (₹)<input name={`unit-cost-${index}`} required type="number" min="0" step="0.01" defaultValue={item?item.materialCost+item.manufacturingCost:undefined} placeholder="₹" onChange={event=>setLineValues(current=>({...current,[index]:{quantity:current[index]?.quantity??item?.quantity??0,unitCost:Number(event.target.value)}}))}/></label><label>Category<select name={`category-${index}`} defaultValue={item?.category??"Sarees"}><option>Sarees</option><option>Salwar suits</option><option>Kurtis</option><option>Blouses</option><option>T-shirts</option><option>Shirts</option><option>Other</option></select></label></div><datalist id="vendor-product-list">{vendors.flatMap(v=>v.products).map(product=><option key={product.id} value={product.name}/>)}</datalist></div>})}<div className="line-editor-head"><strong>Other purchase expenses</strong><button type="button" className="table-action" onClick={()=>setExpenseCount(expenseCount+1)}><Plus size={15}/>Add expense</button></div><p className="form-help">Add worker fees, food allowance, transport, or other costs related to this purchase.</p>{Array.from({length:Math.max(1,expenseCount)}).map((_,index)=>{const item=extraExpenses[index];return <div className="purchase-extra-row" key={item?.id??index}><label>Expense description<input name={`extra-description-${index}`} defaultValue={item?.description} placeholder="Worker fees, food allowance…"/></label><label>Type<select name={`extra-category-${index}`} defaultValue={item?.category??"Other"}><option>Worker fees</option><option>Food allowance</option><option>Transport</option><option>Other</option></select></label><label>Paid to<input name={`extra-payee-${index}`} defaultValue={item?.payee} placeholder="Employee or payee"/></label><label>Amount<input name={`extra-amount-${index}`} type="number" min="0" step="0.01" defaultValue={item?.amount} placeholder="₹" onChange={event=>setExtraValues(current=>({...current,[index]:Number(event.target.value)}))}/></label><button type="button" className="line-remove" aria-label="Remove expense line" onClick={()=>setExpenseCount(Math.max(1,expenseCount-1))}><X size={14}/></button></div>})}<section className="purchase-cost-summary"><h3>Purchase cost summary</h3><div><span>Products subtotal (quantity × cost per unit)</span><strong>{money(productSubtotal)}</strong></div><div><span>Other expenses</span><strong>{money(otherExpenseTotal)}</strong></div><div className="purchase-grand-total"><span>Total purchase cost</span><strong>{money(purchaseGrandTotal)}</strong></div></section><section className="purchase-funding-panel"><div><h3>Funding source for this purchase</h3><p>Choose whose customer receipt the owner will use for this purchase from {purchase?.vendorName||"the selected supplier"}. Each option shows the receipt owner, reference, and remaining funds. The purchase total is checked against that balance when you save.</p></div><label>Customer / receipt<select name="sourcePaymentId" defaultValue={purchase?.sourcePaymentId??""}><option value="">General owner funds / not assigned</option>{receipts.map(receipt=>{const available=Math.max(0,receipt.amount-receiptAllocated(store,receipt.id,purchase?.id??""));return <option key={receipt.id} value={receipt.id}>{receipt.party} · {receipt.reference||receipt.id} · {money(available)} available</option>})}</select></label>{purchase?.sourcePaymentId&&<div className="funding-summary"><span>Receipt owner: <strong>{receipts.find(r=>r.id===purchase.sourcePaymentId)?.party||"Customer"}</strong></span><span>Purchase budget: <strong>{money(purchaseTotal(purchase)+purchaseExtraTotal(purchase))}</strong></span><span>Supplier: <strong>{purchase.vendorName}</strong></span></div>}<span className="form-help">This receipt is reserved for the purchase and appears in Cash flow with the supplier, purchase amount, paid amount, and balance due.</span></section><div className="form-row"><label>Received into warehouse<select name="warehouse"><option>Warehouse A</option><option>Warehouse B</option><option>Storefront</option></select></label><label>Supplier payment<input disabled value={purchase?money(purchase.paid)+" paid":"Unpaid · record supplier payment in Cash flow"}/></label></div>{purchase&&<div className="inline-hint">Sold, returned, and in-process quantities are protected when editing purchase stock.</div>}<div className="hidden-stock-check" aria-hidden="true">{batches.length}</div></>;
}
function ReturnFields({purchase,batches,returned}:{purchase?:Purchase;batches:Batch[];returned?:PurchaseReturn}) {
  const available=(lineId:string)=>batches.filter(b=>b.purchaseId===purchase?.id&&b.lineId===lineId).reduce((s,b)=>s+b.remaining,0)+(returned?.lineId===lineId?returned.quantity:0);
  return <>{purchase&&<><label>Supplier<input readOnly value={purchase.vendorName}/></label><label>Product / original purchase<select name="lineId" required defaultValue={returned?.lineId??""}><option value="">Choose purchase line</option>{purchase.items.filter(i=>available(i.id)>0).map(item=><option key={item.id} value={item.id}>{item.name} · {item.sku||purchase.id} · {available(item.id)} units available</option>)}</select></label><div className="form-row"><label>Quantity to return<input name="quantity" type="number" required min="1" defaultValue={returned?.quantity} placeholder="Units"/></label><label>Return date<input name="date" type="date" defaultValue={returned?.date??isoDate()} required/></label></div><label>Settlement<select name="disposition" defaultValue={returned?.disposition??"Vendor credit"}><option>Vendor credit</option><option>Refund due</option></select></label><label>Reason<input name="reason" defaultValue={returned?.reason} placeholder="Optional return reason"/></label>{returned?.refunded&&<div className="inline-hint">Already refunded: {money(returned.refunded)}. The return value cannot be edited below this amount.</div>}</>}</>;
}
function OrderFields({vendors,batches,count,setCount,order}:{vendors:Vendor[];batches:Batch[];count:number;setCount:(n:number)=>void;order?:Order}) {
  const lines=order?.items??[];
  const products=vendors.flatMap(v=>v.products.map(product=>({...product,vendorName:v.name}))).filter(product=>batches.some(batch=>batch.productId===product.id&&sellableQuantity(batch)>0)||order?.status!=="Draft");
  const availableFor=(productId:string)=>batches.filter(batch=>batch.productId===productId).reduce((sum,batch)=>sum+sellableQuantity(batch),0);
  return <><div className="form-row"><label>Customer / buyer<input name="customer" required defaultValue={order?.customer} placeholder="Buyer or business name"/></label><label>Order type<select name="channel" defaultValue={order?.channel??"Retail"}>{orderTypes.map(type=><option key={type}>{type}</option>)}</select></label></div><label>Order date<input name="date" type="date" required defaultValue={order?.created??isoDate()}/></label><div className="line-editor-head"><strong>Order products</strong><button type="button" className="table-action" onClick={()=>setCount(count+1)}><Plus size={15}/>Add item</button></div>{Array.from({length:Math.max(1,count)}).map((_,index)=>{const line=lines[index];return <div className="sale-line-editor" key={line?.id??index}><button type="button" className="line-remove" aria-label="Remove order line" onClick={()=>setCount(Math.max(1,count-1))}><X size={14}/></button><label>Supplier · product · available<select name={`product-${index}`} required defaultValue={line?.productId??""}><option value="">Choose supplier and product</option>{products.map(product=><option key={product.id} value={product.id}>{product.vendorName} · {product.name} · {availableFor(product.id)} available</option>)}</select></label><div className="form-row"><label>Quantity<input name={`quantity-${index}`} type="number" required={index===0} min="1" defaultValue={line?.quantity} placeholder="0"/></label><label>Price per unit (₹)<input name={`price-${index}`} type="number" required={index===0} min="0.01" step="0.01" defaultValue={line?.price} placeholder="0.00"/></label><label>Tax rate (%)<input name={`tax-${index}`} type="number" min="0" max="100" step="0.01" defaultValue={line?.taxRate??0}/></label></div></div>})}{order&&order.status!=="Draft"&&<div className="inline-hint">This order has been confirmed. Editing changes its order details; stock will be recalculated and reallocated FIFO.</div>}</>;
}
function ProcessFields({batch,initialProcess}:{batch?:Batch;initialProcess:string}){const processing=(batch?.processes??[]).filter(item=>item.status==="In process").reduce((sum,item)=>sum+item.quantity,0);const available=Math.max(0,(batch?.remaining??0)-processing);return <><div className="inline-hint">{batch?.vendorName} · {batch?.product} · {available} units available to send to a process.</div><label>Process<select name="process" required defaultValue={initialProcess}><option>Packing</option><option>Stitching</option><option>Finishing</option><option>Quality check</option><option>Embroidery</option><option>Other</option></select></label><div className="form-row"><label>Quantity<input name="quantity" required type="number" min="1" max={available} defaultValue={available>0?1:undefined}/></label><label>Sent date<input name="date" type="date" required defaultValue={isoDate()}/></label></div><label>Notes<input name="note" placeholder="Optional process details"/></label></>}
function ExpenseFields({expense,store}:{expense?:Expense;store:Store}){const receipts=store.payments.filter(payment=>payment.kind==="Customer receipt");return <><label>Expense date<input name="date" type="date" required defaultValue={expense?.date??isoDate()}/></label><div className="form-row"><label>Expense type<select name="category" defaultValue={expense?.category??"Other"}><option>Salary</option><option>Worker fees</option><option>Food allowance</option><option>Food / snacks</option><option>Transport</option><option>Rent</option><option>Utilities</option><option>Other</option></select></label><label>Paid to<input name="payee" defaultValue={expense?.payee} placeholder="Employee or recipient"/></label></div><label>Description<input name="description" required defaultValue={expense?.description} placeholder="What was this money spent on?"/></label><div className="form-row"><label>Amount<input name="amount" type="number" required min="0.01" step="0.01" defaultValue={expense?.amount} placeholder="₹"/></label><label>Payment method<select name="method" defaultValue={expense?.method??"Cash"}><option>Cash</option><option>Bank transfer</option><option>UPI</option><option>Cheque</option><option>Other</option></select></label></div><label>Paid from customer receipt<select name="sourcePaymentId" defaultValue={expense?.sourcePaymentId??""}><option value="">General cash / bank balance</option>{receipts.map(payment=>{const available=Math.max(0,payment.amount-receiptAllocated(store,payment.id,"",expense?.id??""));return <option key={payment.id} value={payment.id}>{payment.party} · {payment.reference||payment.id} · {money(available)} unassigned</option>})}</select><span className="form-help">Link this expense to a customer receipt to see how that incoming amount was used.</span></label><label>Reference / note<input name="reference" defaultValue={expense?.reference} placeholder="Optional reference"/></label></>}

function PaymentFields({mode,store,target,payment}:{mode:Modal;store:Store;target:string;payment?:Payment}) {
  const kind=payment?.kind??(mode==="supplier-payment"?"Supplier payment":mode==="supplier-refund"?"Supplier refund":"Customer receipt");
  const linkedPurchase=kind==="Supplier payment"?store.purchases.find(p=>p.id===(payment?.linkId||target)):undefined;
  let options:{id:string;label:string;due:number}[]=[];
  if(kind==="Supplier payment") options=store.purchases.filter(p=>purchaseDue(store,p)>0).map(p=>({id:p.id,label:`${p.vendorName} · ${p.id}`,due:purchaseDue(store,p)}));
  if(kind==="Customer receipt") options=store.orders.filter(o=>o.invoice&&saleTotal(o)>o.paid).map(o=>({id:o.id,label:`${o.customer} · ${o.invoice}`,due:saleTotal(o)-o.paid}));
  if(kind==="Supplier refund") options=store.returns.filter(r=>r.amount>r.refunded).map(r=>({id:r.id,label:`${r.vendorName} · ${r.product} · ${r.id}`,due:r.amount-r.refunded}));
  return <><label>{kind==="Supplier payment"?"Purchase / supplier":kind==="Supplier refund"?"Returned purchase":"Invoiced customer order"}<select name="target" required defaultValue={payment?.linkId??target??""}><option value="">Select open balance</option>{options.map(option=><option value={option.id} key={option.id}>{option.label} · due {money(option.due)}</option>)}</select></label><div className="form-row"><label>Amount (₹)<input name="amount" type="number" required min="0.01" step="0.01" defaultValue={payment?.amount} placeholder="0.00"/></label><label>Payment method<select name="method" defaultValue={payment?.method??"Bank transfer"}><option>Bank transfer</option><option>UPI</option><option>Cash</option><option>Cheque</option></select></label></div><div className="form-row"><label>Transaction date<input name="date" type="date" required defaultValue={payment?.date??isoDate()}/></label><label>Reference<input name="reference" defaultValue={payment?.reference} placeholder="Transaction reference"/></label></div>{kind==="Supplier payment"&&(linkedPurchase?.sourcePaymentId?<><input type="hidden" name="sourcePaymentId" value={linkedPurchase.sourcePaymentId}/><div className="inline-hint">This payment to {linkedPurchase.vendorName} is funded from {store.payments.find(p=>p.id===linkedPurchase.sourcePaymentId)?.party||"the customer receipt"}. Purchase budget already reserved.</div></>:<label>Paid from customer receipt<select name="sourcePaymentId" defaultValue={payment?.sourcePaymentId??""}><option value="">General cash / bank balance</option>{store.payments.filter(p=>p.kind==="Customer receipt").map(receipt=>{const unassigned=Math.max(0,receipt.amount-receiptAllocated(store,receipt.id,"","",payment?.id??""));return <option key={receipt.id} value={receipt.id}>{receipt.party} · {receipt.reference||receipt.id} · {money(unassigned)} unassigned</option>})}</select><span className="form-help">Choose the customer receipt this payment is coming from. Its remaining unassigned balance is shown above.</span></label>)}</>;
}
function InvoiceModal({order,profile,payments,onClose,onPrint,onReceive}:{order:Order;profile:Profile;payments:Payment[];onClose:()=>void;onPrint:()=>void;onReceive:()=>void}) {return <div className="modal invoice-modal"><div className="invoice-top"><div><span className="invoice-brand">{profile.name.toUpperCase()}</span><span className="invoice-label">SALES INVOICE</span></div><button className="icon-button" onClick={onClose} aria-label="Close invoice"><X size={20}/></button></div><div className="invoice-parties"><div><span>FROM</span><strong>{profile.name}</strong><small>{profile.address||"Business address not set"}</small><small>{profile.email||"Email not set"} · {profile.phone||"Phone not set"}</small><small>{profile.gstin?`GSTIN ${profile.gstin}`:"GSTIN not set"}</small></div><div><span>TO</span><strong>{order.customer}</strong><small>{order.channel} · Order {order.id}</small></div></div><div className="invoice-number"><div><span>INVOICE NUMBER</span><strong>{order.invoice||"Invoice pending"}</strong></div><div><span>INVOICE DATE</span><strong>{dateText(isoDate())}</strong></div></div><table className="invoice-table"><thead><tr><th>PRODUCT</th><th>QTY</th><th>UNIT PRICE</th><th>AMOUNT</th></tr></thead><tbody>{order.items.map(item=><tr key={item.id}><td>{item.product}</td><td>{item.quantity}</td><td>{money(item.price)}</td><td>{money(item.quantity*item.price)}</td></tr>)}</tbody></table><div className="invoice-totals"><span>Subtotal <strong>{money(saleSubtotal(order))}</strong></span><span>Tax <strong>{money(saleTotal(order)-saleSubtotal(order))}</strong></span><span className="invoice-grand">Invoice total <strong>{money(saleTotal(order))}</strong></span><span>Paid <strong>{money(order.paid)}</strong></span><span>Balance due <strong>{money(Math.max(0,saleTotal(order)-order.paid))}</strong></span></div><div className="invoice-bank"><strong>Bank details</strong><span>{profile.bank||"Bank not set"} · {profile.accountName||profile.name}</span><span>Account {profile.accountNumber||"not set"} · IFSC {profile.ifsc||"not set"}</span></div>{payments.length>0&&<div className="invoice-bank"><strong>Payment history</strong>{payments.map(item=><span key={item.id}>{dateText(item.date)} · {item.method} · {money(item.amount)} · {item.reference}</span>)}</div>}<div className="modal-actions"><button className="button secondary" onClick={onPrint}><Printer size={17}/>Print invoice</button>{saleTotal(order)>order.paid&&<button className="button primary" onClick={onReceive}><Plus size={17}/>Record payment</button>}</div></div>; }
